-- =============================================================================
-- 451 — LE CAHIER D'EXERCICES DE TLE (partie 16)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 451 --niveau Tle --matieres ses --suffixe 16 > supabase/contenu/451_exercices_tle_16.sql
--
-- 93 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   ses.k191                33 exercices · 11 chapitres
--   ses.k192                33 exercices · 11 chapitres
--   ses.k193                27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('5cf9270b-c9ef-58af-9b8a-21f90dfb0313'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Six familles d’actifs","competence":"lire-tableau","situation":"Malik découvre comment l’INSEE répartit les actifs qui ont un emploi en six grands groupes. Avant de comparer avec sa ville, il veut bien lire ce tableau.","documents":[{"id":"pcs","type":"tableau","titre":"Les actifs occupés selon la PCS","source":"Ordres de grandeur arrondis, d’après l’INSEE (enquête Emploi, début des années 2020).","colonnes":["Groupe de PCS","Part des actifs occupés (%)"],"lignes":[["Agriculteurs exploitants",1],["Artisans, commerçants, chefs d’entreprise",6],["Cadres et professions intellectuelles supérieures",21],["Professions intermédiaires",26],["Employés",27],["Ouvriers",19]],"enteteLignes":true}],"questions":[{"enonce":"Touche le groupe le plus nombreux parmi les actifs occupés.","aide":"Cherche le plus grand pourcentage de la colonne de droite.","type":"zone","document":"pcs","multiple":false},{"enonce":"Quelle part des actifs occupés, en %, les employés et les ouvriers représentent-ils ensemble ?","aide":"Additionne deux lignes du tableau.","type":"nombre","unite":"%"},{"enonce":"Dans une commune imaginée de 2 000 actifs occupés qui aurait exactement cette répartition, combien y aurait-il de cadres et de professions intellectuelles supérieures ?","aide":"Calcule 21 % de 2 000 : 2 000 × 21 ÷ 100.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r4c0"]},"explication":"Les **employés** forment le groupe le plus nombreux, avec 27 % des actifs occupés."},{"cle":{"type":"nombre","valeur":46,"tolerance":0},"affichage":"46 %","explication":"27 + 19 = **46 %** : près d’un actif occupé sur deux est employé ou ouvrier."},{"cle":{"type":"nombre","valeur":420,"tolerance":0},"affichage":"420","explication":"2 000 × 0,21 = **420 cadres**."}]$ex$::jsonb),
  ('5cf9270b-c9ef-58af-9b8a-21f90dfb0313'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Même âge, autre génération","competence":"raisonner","situation":"Deux générations sont comparées à 30 et à 50 ans. Les revenus sont exprimés en euros constants : l’inflation est déjà retirée. Deux effets se mélangent facilement : celui de l’âge et celui de la génération.","documents":[{"id":"rev","type":"tableau","titre":"Revenu mensuel moyen (euros constants)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Génération","À 30 ans","À 50 ans"],"lignes":[["Née en 1950",1500,2400],["Née en 1970",1800,2700]],"enteteLignes":true}],"questions":[{"enonce":"Dans la génération née en 1950, de combien le revenu a-t-il augmenté, en %, entre 30 et 50 ans ?","aide":"Taux de variation = (valeur finale − valeur initiale) ÷ valeur initiale. Ici : (2 400 − 1 500) ÷ 1 500.","type":"nombre","unite":"%"},{"enonce":"Quand on suit une même génération entre 30 et 50 ans, la hausse de revenu mesure surtout…","aide":"Ici, la génération ne change pas : qu’est-ce qui change ?","type":"choix","options":[{"id":"a","texte":"un effet de la PCS uniquement"},{"id":"b","texte":"un effet de génération : l’année de naissance"},{"id":"c","texte":"un effet d’âge : la position dans le cycle de vie"},{"id":"d","texte":"un effet du diplôme uniquement"}],"multiple":false},{"enonce":"Pour isoler un effet de génération, il faut comparer les deux générations au même âge. Touche les deux cases à comparer à 50 ans.","aide":"Les deux cases doivent être dans la même colonne.","type":"zone","document":"rev","multiple":true},{"enonce":"À 50 ans, de combien, en %, le revenu de la génération née en 1970 dépasse-t-il celui de la génération née en 1950 ?","aide":"(2 700 − 2 400) ÷ 2 400.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":60,"tolerance":0},"affichage":"60 %","explication":"(2 400 − 1 500) ÷ 1 500 = 0,6, soit **+60 %**."},{"cle":{"type":"choix","ids":["c"]},"explication":"La génération est la même ; seul l’**âge** change. La hausse de revenu au fil de la carrière est d’abord un **effet d’âge**."},{"cle":{"type":"zone","ids":["r0c2","r1c2"]},"explication":"À 50 ans, on lit **2 400** (née en 1950) et **2 700** (née en 1970) : l’âge est le même, seule la génération diffère."},{"cle":{"type":"nombre","valeur":12.5,"tolerance":0},"affichage":"12,5 %","explication":"(2 700 − 2 400) ÷ 2 400 = 0,125, soit **+12,5 %** : c’est un effet de génération."}]$ex$::jsonb),
  ('5cf9270b-c9ef-58af-9b8a-21f90dfb0313'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quand les écarts se cumulent","competence":"raisonner","situation":"Une chaîne de désavantages relie le diplôme à la santé. Deux foyers imaginés permettent de mesurer si les écarts restent les mêmes d’un domaine à l’autre.","documents":[{"id":"chaine","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Faible diplôme"},{"id":"z2","texte":"Emploi peu qualifié"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Logement éloigné des services"},{"id":"z5","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"foyers","type":"tableau","titre":"Deux foyers imaginés","source":"Situations inventées pour l’exercice.","colonnes":["","Foyer A","Foyer B"],"lignes":[["Profession","Cadre","Ouvrier"],["Diplôme","Master","CAP"],["Revenu mensuel (€)","3 200","1 600"],["Patrimoine (€)","240 000","12 000"]],"enteteLignes":true}],"questions":[{"enonce":"Complète les deux maillons manquants de la chaîne.","aide":"Plus on avance dans la chaîne, plus les désavantages s’ajoutent.","type":"trous","segments":["Troisième maillon : un revenu ",0,". Dernier maillon : une santé ",1,"."],"banque":["dégradée","renforcée","plus élevé","plus faible"]},{"enonce":"Combien de fois le revenu du foyer A est-il plus élevé que celui du foyer B ?","aide":"Divise 3 200 par 1 600.","type":"nombre","unite":"fois"},{"enonce":"Combien de fois le patrimoine du foyer A est-il plus élevé que celui du foyer B ?","aide":"Divise 240 000 par 12 000.","type":"nombre","unite":"fois"},{"enonce":"Que montre la comparaison des deux rapports (2 et 20) ?","aide":"Compare 2 et 20 : lequel des deux écarts est le plus fort ?","type":"choix","options":[{"id":"a","texte":"Que le diplôme n’a aucun effet sur le patrimoine, qui dépend uniquement de la chance"},{"id":"b","texte":"Que les deux foyers sont à égalité de ressources, malgré des revenus différents"},{"id":"c","texte":"Que le revenu est le seul facteur qui structure la société, le patrimoine comptant peu"},{"id":"d","texte":"Que l’écart de patrimoine dépasse l’écart de revenu : les désavantages se cumulent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["plus faible"],["degradee"]]},"affichage":"plus faible · dégradée","explication":"Un emploi peu qualifié donne un **revenu plus faible** ; un logement éloigné des services et des moyens réduits conduisent à une **santé dégradée**. Chaque désavantage en appelle un autre."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 fois","explication":"3 200 ÷ 1 600 = **2**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 fois","explication":"240 000 ÷ 12 000 = **20**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le revenu est **2 fois** plus élevé, le patrimoine **20 fois** : les écarts s’additionnent et se multiplient. C’est le **cumul** des inégalités qui structure la société."}]$ex$::jsonb),
  ('a99fa28c-d982-51b3-9465-ac45947efc00'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Cadres et ouvriers : le grand déplacement","competence":"lire-graphique","situation":"Rayan compare la place de deux groupes dans la population active il y a soixante-dix ans et aujourd’hui. Le graphique l’aide à mesurer le changement.","documents":[{"id":"gr","type":"graphique","forme":"barres","titre":"Part dans la population active (%)","source":"Ordres de grandeur arrondis, d’après l’INSEE ; « aujourd’hui » = début des années 2020.","categories":["Cadres","Ouvriers"],"series":[{"nom":"Vers 1950","valeurs":[3,40],"teinte":"gris"},{"nom":"Aujourd’hui","valeurs":[20,20],"teinte":"turquoise"}],"axeY":{"titre":"Part des actifs","unite":"en %","min":0,"max":50,"pas":10},"axeX":{"titre":"Groupe"},"valeurs":false}],"questions":[{"enonce":"Touche le groupe dont la part a été divisée par deux.","aide":"Compare la barre grise et la barre turquoise de chaque groupe.","type":"zone","document":"gr","multiple":false},{"enonce":"De combien de points de pourcentage la part des ouvriers a-t-elle baissé ?","aide":"Une baisse en points se calcule par soustraction : 40 − 20.","type":"nombre","unite":"points"},{"enonce":"Par combien la part des cadres a-t-elle été multipliée entre les deux dates ? Arrondis au dixième.","aide":"Coefficient multiplicateur = valeur finale ÷ valeur initiale : 20 ÷ 3.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"La part des **ouvriers** est passée de 40 % à 20 % : elle a été divisée par deux."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 points","explication":"40 − 20 = **20 points de pourcentage**."},{"cle":{"type":"nombre","valeur":6.7,"tolerance":0.05},"affichage":"6,7","explication":"20 ÷ 3 ≈ **6,7** : la part des cadres a été multipliée par environ 6,7."}]$ex$::jsonb),
  ('a99fa28c-d982-51b3-9465-ac45947efc00'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le bac pour presque tous, mais pas à égalité","competence":"lire-graphique","situation":"La massification scolaire a fait grimper la part de bacheliers. Mais qui en a profité ? Lina lit un graphique national, puis compare deux milieux dans un échantillon imaginaire.","documents":[{"id":"bac","type":"graphique","forme":"barres","titre":"Bacheliers dans une génération","source":"Ordres de grandeur arrondis.","categories":["1950","1970","1985","1995","2020"],"series":[{"nom":"Part de bacheliers","valeurs":[5,20,30,60,80],"teinte":"violet"}],"axeY":{"titre":"Part de la génération","unite":"en %","min":0,"max":100,"pas":20},"axeX":{"titre":"Année"},"valeurs":false},{"id":"milieux","type":"tableau","titre":"Bacheliers selon le milieu (sur 100 élèves de chaque milieu)","source":"Chiffres inventés pour l’exercice.","colonnes":["Milieu","1985","2020"],"lignes":[["Enfants de cadres",70,95],["Enfants d’ouvriers",25,75]],"enteteLignes":true}],"questions":[{"enonce":"Par combien la part de bacheliers a-t-elle été multipliée entre 1950 et 2020 ?","aide":"Coefficient multiplicateur = 80 ÷ 5.","type":"nombre"},{"enonce":"La part de bacheliers a gagné 15, 10, 30 puis 20 points entre deux dates successives. Touche la date où s’achève la plus forte hausse.","aide":"Calcule la différence entre chaque barre et la précédente.","type":"zone","document":"bac","multiple":false},{"enonce":"Dans le tableau, quel est l’écart, en points, entre la part de bacheliers des enfants de cadres et celle des enfants d’ouvriers en 2020 ?","aide":"En 2020 : 95 − 75.","type":"nombre","unite":"points"},{"enonce":"Que peut-on conclure de l’ensemble des deux documents ?","aide":"Regarde si l’ordre entre les deux lignes a changé entre 1985 et 2020.","type":"choix","options":[{"id":"a","texte":"La massification n’a profité à aucun milieu social : les taux d’accès au bac n’ont pas bougé"},{"id":"b","texte":"L’écart entre les deux milieux est aujourd’hui nul : l’origine sociale n’a plus d’effet scolaire"},{"id":"c","texte":"Les enfants d’ouvriers ont rattrapé puis dépassé les enfants de cadres dans l’accès au bac général"},{"id":"d","texte":"Le niveau de tous a progressé, mais les enfants de cadres restent devant : les positions relatives demeurent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"80 ÷ 5 = **16** : la part de bacheliers a été multipliée par 16."},{"cle":{"type":"zone","ids":["k3"]},"explication":"Entre 1985 et 1995, la part passe de 30 % à 60 % : **+30 points**, la plus forte hausse. Elle s’achève en **1995**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 points","explication":"En 2020, l’écart est de 95 − 75 = **20 points** (contre 45 points en 1985)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les deux milieux progressent (70 → 95 et 25 → 75), mais les enfants de cadres gardent **la première place** : le niveau s’élève **sans rebattre les rangs**."}]$ex$::jsonb),
  ('a99fa28c-d982-51b3-9465-ac45947efc00'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Moyennisation ou polarisation ?","competence":"analyser-document","situation":"Lina et Noa débattent de la société française. Elles s’appuient sur un tableau imaginaire qui suit les emplois selon leur qualification entre 1990 et 2020.","documents":[{"id":"emplois","type":"tableau","titre":"Variation du nombre d’emplois entre 1990 et 2020 (en milliers)","source":"Chiffres imaginés pour l’exercice, dans le sens des évolutions observées.","colonnes":["Type d’emplois","Variation"],"lignes":[["Emplois très qualifiés","+ 3 000"],["Emplois de qualification intermédiaire","− 1 500"],["Emplois peu qualifiés de services","+ 1 200"],["Emplois d’ouvriers de l’industrie","− 800"]],"enteteLignes":true},{"id":"debat","type":"dialogue","modele":"sms","participants":[{"nom":"Lina","emoji":"👩","cote":"gauche"},{"nom":"Noa","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Tout le monde est plus diplômé qu’en 1950. La société est devenue une grande classe moyenne."},{"qui":"Noa","texte":"Oui, mais depuis les années 1980 les écarts de patrimoine se sont creusés."},{"qui":"Lina","texte":"Et l’emploi ? Les emplois du milieu reculent…"}]}],"questions":[{"enonce":"Touche la ligne qui montre le recul des emplois du milieu de l’échelle.","aide":"Cherche la ligne qui n’est ni tout en haut, ni tout en bas de l’échelle de qualification.","type":"zone","document":"emplois","multiple":false},{"enonce":"Quel est le solde net d’emplois créés entre 1990 et 2020, en milliers ?","aide":"Additionne toutes les variations, avec leur signe : + 3 000 − 1 500 + 1 200 − 800.","type":"nombre","unite":"milliers"},{"enonce":"Associe chaque thèse à son contenu.","aide":"Le tableau illustre l’une des deux thèses.","type":"association","gauche":[{"id":"g0","texte":"Moyennisation (années 1960-1970)"},{"id":"g1","texte":"Polarisation (depuis les années 1990)"}],"droite":[{"id":"d0","texte":"Emplois très qualifiés et peu qualifiés progressent, emplois intermédiaires reculent"},{"id":"d1","texte":"Une vaste classe moyenne absorbe les extrêmes"}]},{"enonce":"Quelle conclusion de copie respecte les deux constats de Lina et de Noa ?","aide":"Une bonne copie ne choisit pas entre deux constats exacts.","type":"choix","options":[{"id":"a","texte":"Seule la moyennisation est vraie : les inégalités de revenu et de patrimoine ont disparu"},{"id":"b","texte":"La société s’est enrichie et qualifiée pour presque tous, mais les écarts de patrimoine se sont creusés"},{"id":"c","texte":"Seule la polarisation est vraie : le niveau de diplôme n’a pas changé depuis cinquante ans"},{"id":"d","texte":"Il faut choisir une seule thèse et ignorer l’autre, pour que la copie reste cohérente"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Les emplois de **qualification intermédiaire** reculent de 1 500 milliers : c’est le signe d’une polarisation."},{"cle":{"type":"nombre","valeur":1900,"tolerance":0},"affichage":"1900 milliers","explication":"3 000 − 1 500 + 1 200 − 800 = **+1 900 milliers** d’emplois."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"La **moyennisation** décrit une société qui se resserre autour du milieu ; la **polarisation** décrit une société qui s’écarte vers le haut et le bas."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les deux constats se tiennent **ensemble** : élévation du niveau de qualification pour presque tous **et** creusement des écarts de patrimoine."}]$ex$::jsonb),
  ('7b0a0111-cd13-5214-a5c9-a892c4c3b2ca'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui parle : Marx, Weber ou Bourdieu ?","competence":"analyser-document","situation":"En cours de SES, Emma résume trois auteurs sur une affiche. Elle doit ensuite attribuer à chacun des phrases entendues en classe.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Trois découpages de la société","sousTitre":"Affiche de la classe de Tle","emoji":"📚","lignes":[{"texte":"Marx","valeur":"Deux classes en conflit","id":"z1"},{"texte":"Weber","valeur":"Trois ordres : économique, social, politique","id":"z2"},{"texte":"Bourdieu","valeur":"Trois capitaux et un habitus","id":"z3"}],"pied":"Affiche écrite pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Touche l’auteur qui découpe la société en deux classes seulement.","aide":"Le nombre de classes est dans la colonne de droite.","type":"zone","document":"affiche","multiple":false},{"enonce":"Touche l’auteur qui parle d’habitus.","aide":"L’habitus est associé aux capitaux.","type":"zone","document":"affiche","multiple":false},{"enonce":"Attribue chaque phrase à l’auteur qui la dirait le mieux.","aide":"Associe chaque phrase à un mot clé de l’affiche : rapports de production, prestige, partis, capitaux.","type":"categories","categories":[{"id":"c0","texte":"Marx"},{"id":"c1","texte":"Weber"},{"id":"c2","texte":"Bourdieu"}],"items":[{"id":"i0","texte":"« Les deux camps ont des intérêts qui s’opposent. »"},{"id":"i1","texte":"« Les partis cherchent à conquérir le pouvoir. »"},{"id":"i2","texte":"« Ce qui compte, c’est qui possède l’usine et qui vend son travail. »"},{"id":"i3","texte":"« Son réseau de relations l’a aidé à trouver un stage. »"},{"id":"i4","texte":"« Notaire ou professeure : même grand prestige, revenus différents. »"},{"id":"i5","texte":"« On va au musée, on parle avec aisance : un capital culturel hérité. »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**Marx** oppose deux classes, la bourgeoisie et le prolétariat."},{"cle":{"type":"zone","ids":["z3"]},"explication":"L’**habitus** est le concept de **Bourdieu** : les dispositions incorporées par la socialisation."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c2","i4":"c1","i5":"c2"}},"explication":"**Marx** : propriété des moyens de production et conflit. **Weber** : prestige (ordre social) et partis (ordre politique). **Bourdieu** : capital culturel et capital social."}]$ex$::jsonb),
  ('7b0a0111-cd13-5214-a5c9-a892c4c3b2ca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le notaire et le professeur","competence":"analyser-document","situation":"Pour Weber, la hiérarchie de l’argent n’est pas la seule. Un sondage imaginaire note le prestige de quatre personnes (sur 10) et donne leur revenu mensuel.","documents":[{"id":"personnes","type":"tableau","titre":"Quatre personnes imaginées","source":"Chiffres et notes de sondage imaginés pour l’exercice.","colonnes":["Personne","Métier","Revenu mensuel (€)","Prestige (sur 10)"],"lignes":[["Claire","Notaire","6 500",8],["Hugo","Professeur","2 600",8],["Sam","Chef de chantier","3 000",4],["Lou","Cadre commercial","5 000",5]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux personnes qui ont le même prestige mais des revenus très différents.","aide":"Cherche deux notes de prestige identiques dans la dernière colonne.","type":"zone","document":"personnes","multiple":true},{"enonce":"Combien de fois le revenu de Claire est-il plus élevé que celui de Hugo ?","aide":"Divise 6 500 par 2 600.","type":"nombre","unite":"fois"},{"enonce":"Touche les deux personnes qui gagnent plus que Hugo mais qui ont moins de prestige que lui.","aide":"Compare d’abord le revenu à 2 600 €, puis le prestige à 8.","type":"zone","document":"personnes","multiple":true},{"enonce":"Que montre ce tableau, pour Weber ?","aide":"Le revenu relève de l’ordre économique, le prestige de l’ordre social.","type":"choix","options":[{"id":"a","texte":"Que l’ordre économique et l’ordre social ne se recouvrent pas"},{"id":"b","texte":"Que le prestige dépend uniquement du revenu"},{"id":"c","texte":"Que la société se divise en deux classes en conflit"},{"id":"d","texte":"Que tous les groupes ont le même habitus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0","r1c0"]},"explication":"**Claire** et **Hugo** ont tous deux 8 sur 10 en prestige, mais 6 500 € contre 2 600 € de revenu."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0},"affichage":"2,5 fois","explication":"6 500 ÷ 2 600 = **2,5**."},{"cle":{"type":"zone","ids":["r2c0","r3c0"]},"explication":"**Sam** (3 000 €, prestige 4) et **Lou** (5 000 €, prestige 5) gagnent plus que Hugo mais sont moins prestigieux."},{"cle":{"type":"choix","ids":["a"]},"explication":"Revenu et prestige ne vont pas toujours de pair : les ordres **économique** et **social** ne se recouvrent pas."}]$ex$::jsonb),
  ('7b0a0111-cd13-5214-a5c9-a892c4c3b2ca'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les classes existent-elles encore ?","competence":"argumenter","situation":"Pour sa dissertation, Jade doit opposer des arguments sur la pertinence des classes sociales aujourd’hui. Elle s’appuie sur une enquête imaginaire et doit trier ses arguments.","documents":[{"id":"enquete","type":"tableau","titre":"Cadres et ouvriers : trois indicateurs","source":"Chiffres imaginés pour l’exercice, dans l’ordre de grandeur des enquêtes.","colonnes":["Indicateur","Cadres","Ouvriers"],"lignes":[["Patrimoine médian (€)","160 000","35 000"],["Couples dont le conjoint est du même groupe (%)",55,45],["Espérance de vie à 35 ans (années)",49,43]],"enteteLignes":true}],"questions":[{"enonce":"Combien de fois le patrimoine médian des cadres dépasse-t-il celui des ouvriers ? Arrondis au dixième.","aide":"Divise 160 000 par 35 000.","type":"nombre","unite":"fois"},{"enonce":"Touche la ligne qui illustre l’homogamie sociale.","aide":"L’homogamie, c’est se mettre en couple avec quelqu’un du même milieu.","type":"zone","document":"enquete","multiple":false},{"enonce":"Trie ces arguments selon la thèse qu’ils soutiennent.","aide":"Les deux premiers arguments se lisent dans le tableau.","type":"categories","categories":[{"id":"c0","texte":"Les classes restent pertinentes"},{"id":"c1","texte":"Les classes s’affaiblissent"}],"items":[{"id":"i0","texte":"Le genre, l’âge ou l’origine créent d’autres clivages"},{"id":"i1","texte":"Le patrimoine reste très inégal selon la PCS"},{"id":"i2","texte":"Les trajectoires sont de plus en plus individualisées"},{"id":"i3","texte":"Les frontières entre groupes sont brouillées par la moyennisation"},{"id":"i4","texte":"L’homogamie sociale reste élevée"},{"id":"i5","texte":"L’espérance de vie varie encore selon la PCS"}]},{"enonce":"Quelle conclusion correspond à ce qu’attend le programme ?","aide":"Le programme n’attend pas un verdict.","type":"choix","options":[{"id":"a","texte":"Affirmer que les classes n’ont jamais changé depuis Marx, malgré les transformations"},{"id":"b","texte":"Affirmer que les classes ont totalement disparu, en s’appuyant sur la moyennisation"},{"id":"c","texte":"Choisir un seul camp sans citer l’autre, afin d’avoir une thèse très tranchée"},{"id":"d","texte":"Opposer les deux séries d’arguments, en les datant et en les appuyant sur des données"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":4.6,"tolerance":0.05},"affichage":"4,6 fois","explication":"160 000 ÷ 35 000 ≈ **4,6**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"La ligne des **couples dont le conjoint est du même groupe** mesure l’homogamie sociale."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Patrimoine, homogamie et espérance de vie plaident pour la **persistance** des classes. Individualisation, autres clivages et brouillage des frontières plaident pour leur **affaiblissement**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le programme attend de **confronter les deux séries d’arguments**, datés et chiffrés, plutôt qu’un verdict tranché."}]$ex$::jsonb),
