   $ex${"titre":"Comment s’engage-t-on au lycée ?","competence":"lire-graphique","situation":"Le conseil de vie lycéenne a interrogé 200 élèves d’un lycée imaginaire : à quelles formes d’engagement ont-ils déjà pris part ?","documents":[{"id":"enq","type":"graphique","forme":"barres-h","titre":"Élèves ayant déjà…","source":"Enquête imaginée pour l’exercice (200 élèves).","categories":["Signé une pétition","Adhéré à une association","Boycotté un produit","Participé à une manifestation","Adhéré à un syndicat"],"series":[{"nom":"Élèves","valeurs":[120,80,60,40,10],"teinte":"violet"}],"axeY":{"titre":"Nombre d’élèves","unite":"sur 200","min":0,"max":140,"pas":20},"valeurs":false}],"questions":[{"enonce":"Touche la forme d’engagement la plus répandue dans ce lycée.","aide":"Cherche la barre la plus longue.","type":"zone","document":"enq","multiple":false},{"enonce":"Quelle part des 200 élèves a déjà participé à une manifestation ? Réponds en %.","aide":"Part = 40 ÷ 200 × 100.","type":"nombre","unite":"%"},{"enonce":"Associe chaque geste à son répertoire d’engagement.","aide":"Pense au vote, au parti ou au syndicat, à l’achat, à la protestation.","type":"association","gauche":[{"id":"g0","texte":"Voter aux élections municipales"},{"id":"g1","texte":"Adhérer à un syndicat"},{"id":"g2","texte":"Boycotter une marque"},{"id":"g3","texte":"Occuper son lycée"}],"droite":[{"id":"d0","texte":"Le militantisme"},{"id":"d1","texte":"La consommation engagée"},{"id":"d2","texte":"Le vote"},{"id":"d3","texte":"L’action protestataire"}]}]}$ex$::jsonb,
