  ('ea367789-cd51-5114-a11d-7ed48d5ab637'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le passager clandestin de l’usine","competence":"analyser-texte","situation":"Dans une usine imaginée, 100 salariés hésitent à faire grève pour obtenir une hausse de salaire. Olson a montré pourquoi une cause commune ne suffit pas toujours à mobiliser.","documents":[{"id":"usine","type":"texte","genre":"article","titre":"Projet de grève chez Delmas","auteur":"Article écrit pour l’exercice","blocs":["Chez Delmas, 100 salariés réclament une hausse de 100 € par mois, valable pour tous les salariés de l’usine si la grève réussit.","Faire grève coûte 200 € de salaire perdu à chaque gréviste. La caisse du syndicat rembourse la moitié de cette perte, mais seulement aux adhérents.","Dans l’atelier de montage, 8 salariés se connaissent depuis dix ans : quand l’un d’eux manque, tout le monde le voit."]}],"questions":[{"enonce":"Si la grève réussit, combien gagne chaque salarié sur une année, en euros ?","aide":"La hausse est de 100 € par mois : combien de mois ?","type":"nombre","unite":"€"},{"enonce":"Quelle différence de gain annuel y a-t-il entre un non-gréviste et un gréviste sans caisse de grève, si la grève réussit ?","aide":"Seul le gréviste perd des jours de salaire.","type":"nombre","unite":"€"},{"enonce":"Pourquoi un salarié rationnel peut-il choisir de ne pas faire grève ?","aide":"Le bien obtenu est collectif : qui en profite ?","type":"choix","options":[{"id":"a","texte":"Il ne connaît personne dans l’usine"},{"id":"b","texte":"Il profitera de la hausse même sans participer : c’est le passager clandestin"},{"id":"c","texte":"Il craint que la hausse soit de 100 € seulement pour les grévistes"},{"id":"d","texte":"Il ne souhaite pas de hausse de salaire"}],"multiple":false},{"enonce":"Classe chaque élément du texte selon la réponse qu’il apporte au paradoxe d’Olson.","aide":"Une incitation sélective est réservée aux participants.","type":"categories","categories":[{"id":"c0","texte":"Incitation sélective"},{"id":"c1","texte":"Taille réduite du groupe"}],"items":[{"id":"i0","texte":"Un service juridique gratuit réservé aux syndiqués"},{"id":"i1","texte":"La caisse de grève versée seulement aux adhérents"},{"id":"i2","texte":"L’absence d’un salarié est visible dans l’atelier de 8 personnes"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1200,"tolerance":0},"affichage":"1200 €","explication":"100 € × 12 mois = **1 200 €** par an, gréviste ou non."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 €","explication":"Le non-gréviste gagne la hausse **sans** perdre 200 € : il gagne **200 € de plus** que le gréviste."},{"cle":{"type":"choix","ids":["b"]},"explication":"La hausse concerne **tous** les salariés : l’individu rationnel a intérêt à laisser les autres payer le coût de la grève. C’est le **passager clandestin** d’Olson."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1"}},"explication":"La **caisse de grève** et le **service juridique** sont réservés aux adhérents : ce sont des **incitations sélectives**. Dans un petit atelier, l’**abstention se voit** : c’est l’effet de la taille réduite."}]$ex$::jsonb),
  ('ea367789-cd51-5114-a11d-7ed48d5ab637'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Moins d’adhérents, plus de causes","competence":"analyser-document","situation":"Dans une ville imaginée, on suit deux manières de s’engager : adhérer à une organisation (parti, syndicat) et soutenir ponctuellement une cause (pétition, don, relais en ligne).","documents":[{"id":"courbes","type":"graphique","forme":"courbe","titre":"Deux façons de s’engager (% des habitants)","source":"Données imaginées pour l’exercice.","categories":["1990","2000","2010","2020"],"series":[{"nom":"Adhérents d’une organisation","valeurs":[20,16,12,10],"teinte":"violet"},{"nom":"Soutien ponctuel à une cause","valeurs":[10,16,30,45],"teinte":"corail"}],"axeY":{"titre":"Part des habitants","unite":"en %","min":0,"max":50,"pas":10},"axeX":{"titre":"Année"}}],"questions":[{"enonce":"Touche l’année où les deux courbes se croisent.","aide":"Cherche le point où les deux séries ont la même valeur.","type":"zone","document":"courbes","multiple":false},{"enonce":"De combien, en %, la part d’adhérents a-t-elle évolué entre 1990 et 2020 ? Donne un nombre négatif.","aide":"(10 − 20) ÷ 20 × 100.","type":"nombre","unite":"%"},{"enonce":"En 2020, combien de fois y a-t-il plus de personnes qui soutiennent ponctuellement une cause que d’adhérents ?","aide":"Divise 45 par 10.","type":"nombre","unite":"fois"},{"enonce":"Range ces gestes selon la forme d’engagement dont ils relèvent.","aide":"Demande-toi si le geste dure ou s’il est ponctuel.","type":"categories","categories":[{"id":"c0","texte":"Centré sur une organisation"},{"id":"c1","texte":"Centré sur une cause"}],"items":[{"id":"i0","texte":"Tenir une permanence de section d’un parti"},{"id":"i1","texte":"Signer une pétition en ligne"},{"id":"i2","texte":"Relayer un appel à boycotter une marque"},{"id":"i3","texte":"Participer à un week-end de mobilisation pour le climat"},{"id":"i4","texte":"Cotiser chaque mois à un syndicat"}]},{"enonce":"Quelle interprétation est correcte ?","aide":"Regarde les deux courbes ensemble.","type":"choix","options":[{"id":"a","texte":"Les organisations traditionnelles se renforcent, et leurs effectifs augmentent chaque année"},{"id":"b","texte":"L’adhésion recule mais l’engagement change de forme : plus ponctuel, centré sur des causes"},{"id":"c","texte":"L’engagement politique disparaît, puisque les adhésions aux organisations reculent partout"},{"id":"d","texte":"Les habitants ne se mobilisent plus du tout pour des causes, même à l’échelle locale"}],"multiple":false}]}$ex$::jsonb,
