  ('388c0eed-c379-5ea1-a483-901e1a57ccaa'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Des conflits qui changent de visage","competence":"lire-graphique","situation":"Dans une région imaginée, on compte pour 1 000 salariés les journées de grève et les recours aux prud’hommes. Deux tendances se dessinent entre 1990 et 2020.","documents":[{"id":"conf","type":"graphique","forme":"barres","titre":"Conflits du travail pour 1 000 salariés","source":"Données imaginées pour l’exercice.","categories":["1990","2000","2010","2020"],"series":[{"nom":"Journées de grève","valeurs":[120,80,50,30],"teinte":"gris"},{"nom":"Recours aux prud’hommes","valeurs":[10,20,30,40],"teinte":"violet"}],"axeY":{"titre":"Pour 1 000 salariés","min":0,"max":140,"pas":20},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Par combien les journées de grève ont-elles été multipliées entre 1990 et 2020 ? Donne le coefficient multiplicateur.","aide":"Coefficient multiplicateur = valeur finale ÷ valeur initiale : 30 ÷ 120.","type":"nombre"},{"enonce":"De combien, en %, les recours aux prud’hommes ont-ils augmenté entre 1990 et 2020 ?","aide":"(40 − 10) ÷ 10 × 100.","type":"nombre","unite":"%"},{"enonce":"Touche la première année où les recours aux prud’hommes dépassent les journées de grève.","aide":"Compare les deux barres de chaque année.","type":"zone","document":"conf","multiple":false},{"enonce":"Classe ces conflits selon qu’ils sont individualisés ou diversifiés.","aide":"Un conflit individualisé oppose une personne à son employeur devant un juge.","type":"categories","categories":[{"id":"c0","texte":"Individualisé"},{"id":"c1","texte":"Diversifié"}],"items":[{"id":"i0","texte":"Un salarié saisit les prud’hommes"},{"id":"i1","texte":"Une salariée conteste son licenciement devant le juge"},{"id":"i2","texte":"Un refus collectif de faire des heures supplémentaires"},{"id":"i3","texte":"Un débrayage de dix minutes à la prise de poste"}]},{"enonce":"Que montrent ces données ?","aide":"Regarde ce que fait la courbe des recours pendant que la grève recule.","type":"choix","options":[{"id":"a","texte":"Les conflits ne disparaissent pas : ils deviennent plus individuels"},{"id":"b","texte":"Les syndicats ont gagné partout, donc les conflits n’ont plus de raison d’être"},{"id":"c","texte":"Les salariés ne se plaignent plus, car leurs conditions de travail s’améliorent"},{"id":"d","texte":"Les conflits du travail ont disparu, puisque les grèves sont moins fréquentes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.25,"tolerance":0},"affichage":"0,25","explication":"30 ÷ 120 = **0,25** : les journées de grève ont été divisées par quatre, soit − 75 %."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 %","explication":"(40 − 10) ÷ 10 = 3, soit **+300 %** : les recours ont été multipliés par 4."},{"cle":{"type":"zone","ids":["k3"]},"explication":"En **2020**, les recours (40) dépassent les journées de grève (30) ; en 2010, c’était l’inverse (30 contre 50)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Les **recours prud’homaux** individualisent le conflit ; les **débrayages courts** et le **refus d’heures supplémentaires** le diversifient. Le conflit ne disparaît pas : il change de forme."},{"cle":{"type":"choix","ids":["a"]},"explication":"La grève recule mais les **recours individuels augmentent** : les conflits se sont **individualisés et diversifiés**."}]$ex$::jsonb),
  ('388c0eed-c379-5ea1-a483-901e1a57ccaa'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un rond-point, deux revendications","competence":"analyser-texte","situation":"Lors d’une mobilisation imaginée, inspirée de celles de ces dernières années, des habitants se retrouvent sur un rond-point. Deux documents permettent de comprendre ce qu’ils demandent et comment ils s’organisent.","documents":[{"id":"rond","type":"texte","genre":"article","titre":"Samedi sur le rond-point","auteur":"Texte écrit pour l’exercice","blocs":["Nadia et ses voisins discutent. « Avec les taxes sur le carburant et des salaires qui n’augmentent pas, on ne finit plus les mois », dit Nadia.","Karim ajoute : « Et on veut surtout être écoutés et reconnus. Personne ne nous représente : on s’est organisés sur les réseaux sociaux, sans chef ni porte-parole. »"]},{"id":"chiffres","type":"tableau","titre":"Une mobilisation en chiffres","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Valeur"],"lignes":[["Soutiens en ligne","48 000"],["Personnes présentes sur le terrain","600"],["Porte-parole désigné","Aucun"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui relèvent d’une revendication de répartition.","aide":"Pense aux sujets d’argent : ce que l’on paie, ce que l’on gagne.","type":"zone","document":"rond","multiple":true},{"enonce":"Touche les deux mots qui relèvent d’une demande de reconnaissance.","aide":"Pense à ce que Karim veut pour lui et ses voisins, au-delà de l’argent.","type":"zone","document":"rond","multiple":true},{"enonce":"Que montre ce texte sur la lecture « anciens contre nouveaux mouvements » ?","aide":"Compare ce que demandent Nadia et Karim.","type":"choix","options":[{"id":"a","texte":"Seule la répartition est une vraie revendication, la reconnaissance étant secondaire"},{"id":"b","texte":"Les nouveaux mouvements n’ont plus aucun enjeu matériel, seulement des enjeux culturels"},{"id":"c","texte":"Un même mouvement peut porter à la fois une demande de répartition et de reconnaissance"},{"id":"d","texte":"Un mouvement ne porte jamais qu’une seule revendication, matérielle ou symbolique"}],"multiple":false},{"enonce":"Combien de soutiens en ligne y a-t-il pour une personne présente sur le terrain ?","aide":"Divise 48 000 par 600.","type":"nombre","unite":"soutiens"},{"enonce":"Complète la phrase.","aide":"Qui négocierait avec les pouvoirs publics ?","type":"trous","segments":["Un mouvement massif mais sans porte-parole légitime peut rester sans ",0,"."],"banque":["interlocuteur","adhérent","syndicat","budget"]}]}$ex$::jsonb,
