   $ex${"titre":"Quand baisser les prix aggrave les dettes","competence":"raisonner","situation":"Irving Fisher a décrit la déflation par la dette. Un cycle et l’exemple d’un ménage imaginaire permettent de comprendre pourquoi la baisse des prix, en 1929, a aggravé la crise.","documents":[{"id":"cycle","type":"chaine","disposition":"cycle","noeuds":[{"id":"z1","texte":"Les prix baissent"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Les débiteurs vendent pour rembourser"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z1","texte":"nouvelle baisse"}]},{"id":"menage","type":"tableau","titre":"Un ménage endetté","source":"Situation imaginée pour l’exercice.","colonnes":["","Avant la baisse","Après une baisse des prix de 20 %"],"lignes":[["Valeur de la maison (€)","100 000","80 000"],["Dette restant à rembourser (€)","100 000","100 000"]],"enteteLignes":true}],"questions":[{"enonce":"Que faut-il écrire à la place du « ? » dans le cycle ?","aide":"Quand les prix baissent, la dette en euros ne change pas : que devient son poids ?","type":"choix","options":[{"id":"a","texte":"Les dettes sont effacées"},{"id":"b","texte":"La valeur réelle des dettes diminue"},{"id":"c","texte":"Les salaires sont relevés"},{"id":"d","texte":"La valeur réelle des dettes augmente"}],"multiple":false},{"enonce":"Après la baisse, de combien d’euros la dette dépasse-t-elle la valeur de la maison ?","aide":"Soustrais la valeur de la maison à la dette après la baisse.","type":"nombre","unite":"€"},{"enonce":"Quand les prix baissent de 20 %, de combien, en %, la valeur réelle de la dette augmente-t-elle ? Arrondis à l’unité.","aide":"Une baisse de 20 % correspond à un coefficient multiplicateur de 0,8. La valeur réelle est divisée par 0,8.","type":"nombre","unite":"%"},{"enonce":"Pourquoi ce mécanisme aggrave-t-il la crise ?","aide":"Observe le dernier maillon du cycle.","type":"choix","options":[{"id":"a","texte":"Les banques prêtent davantage quand les prix baissent, ce qui relance la demande"},{"id":"b","texte":"Les débiteurs vendent pour rembourser, ce qui fait encore baisser les prix"},{"id":"c","texte":"Les prix qui baissent augmentent les revenus des débiteurs, qui remboursent plus vite"},{"id":"d","texte":"La valeur des maisons augmente, ce qui rend les débiteurs plus riches"}],"multiple":false}]}$ex$::jsonb,
