   $ex$[{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 points","explication":"4 − 0 = **4 points de pourcentage**."},{"cle":{"type":"zone","ids":["k3"]},"explication":"Dès **2010**, le taux est à zéro : la banque centrale ne peut plus le baisser."},{"cle":{"type":"nombre","valeur":1080,"tolerance":0},"affichage":"1080 milliards €","explication":"60 × 18 = **1 080 milliards d’euros**."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"L’**assouplissement quantitatif** fait baisser les taux longs, la **forward guidance** ancre les anticipations, les **prêts de long terme** encouragent le crédit."}]$ex$::jsonb),
  ('b61bd151-8888-5d9c-bd23-8a7f1a52ecfe'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Supervision et prêteur en dernier ressort","competence":"modeliser","situation":"Une banque imaginée doit respecter une règle prudentielle, puis connaît une journée de panique. Deux outils interviennent : le ratio de fonds propres et le prêteur en dernier ressort.","documents":[{"id":"ratio","type":"tableau","titre":"La banque Belmont","source":"Banque et règle imaginées pour l’exercice.","colonnes":["Indicateur","Montant"],"lignes":[["Fonds propres (M€)",6],["Actifs pondérés par le risque (M€)",100],["Exigence minimale (% des actifs pondérés)",8]],"enteteLignes":true},{"id":"panique","type":"fiche","modele":"affiche","entete":"Banque Belmont : lundi","sousTitre":"Journée de panique","emoji":"🏦","lignes":[{"texte":"Dépôts totaux","valeur":"100 M€"},{"texte":"Retraits demandés dans la journée","valeur":"12 M€"},{"texte":"Liquidités en caisse","valeur":"8 M€"}],"pied":"Chiffres imaginés","teinte":"corail"}],"questions":[{"enonce":"Quel est le ratio de fonds propres de Belmont, en % des actifs pondérés ?","aide":"Ratio = fonds propres ÷ actifs pondérés × 100.","type":"nombre","unite":"%"},{"enonce":"De combien de millions d’euros de fonds propres Belmont manque-t-elle pour atteindre 8 % ?","aide":"8 % de 100 M€, moins 6 M€.","type":"nombre","unite":"M€"},{"enonce":"Touche la ligne du montant par lequel on divise les fonds propres pour calculer le ratio.","aide":"Les fonds propres sont rapportés à des actifs pondérés par le risque.","type":"zone","document":"ratio","multiple":false},{"enonce":"Combien de millions d’euros manque-t-il à Belmont lundi pour honorer les retraits ?","aide":"Retraits demandés moins liquidités en caisse.","type":"nombre","unite":"M€"},{"enonce":"Trie ces actions selon qu’elles respectent ou non la règle de Bagehot.","aide":"Bagehot demande trois conditions : largement, taux de pénalité, bonnes garanties.","type":"categories","categories":[{"id":"c0","texte":"Conforme à Bagehot"},{"id":"c1","texte":"Contraire à Bagehot"}],"items":[{"id":"i0","texte":"Prêter très peu, pour punir les banques"},{"id":"i1","texte":"Prêter sans garantie, à taux zéro"},{"id":"i2","texte":"Prêter à un taux de pénalité"},{"id":"i3","texte":"Refuser de prêter à une banque solvable mais illiquide"},{"id":"i4","texte":"Prêter largement à la banque en difficulté"},{"id":"i5","texte":"Prêter contre de bonnes garanties"}]}]}$ex$::jsonb,
