  ('be56bb0c-52c5-56b2-80d0-f7d19153f929'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Chômeur ou pas chômeur ?","competence":"analyser-document","situation":"L’INSEE applique la définition du BIT : pour être chômeur, il faut remplir trois conditions à la fois. Cinq personnes imaginaires sont passées au crible, puis on calcule un taux dans une commune fictive.","documents":[{"id":"pers","type":"tableau","titre":"Cinq situations","source":"Situations imaginées pour l’exercice.","colonnes":["Personne","Semaine de référence","Disponible sous 2 semaines ?","Recherche active ce mois-ci ?"],"lignes":[["Ana","A travaillé 2 heures","Oui","Oui"],["Bilal","Aucune heure travaillée","Oui","Oui"],["Chloé","Aucune heure travaillée","Oui","Non"],["Dylan","Aucune heure travaillée","Non (part à l’étranger)","Oui"],["Élise","Aucune heure travaillée","Oui","Oui"]],"enteteLignes":true},{"id":"commune","type":"tableau","titre":"Une commune imaginaire (15 ans ou plus)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Catégorie","Personnes"],"lignes":[["Actifs occupés","4 500"],["Chômeurs au sens du BIT","500"],["Inactifs","5 000"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux personnes qui sont chômeuses au sens du BIT.","aide":"Il faut les trois conditions : sans emploi, disponible, recherche active.","type":"zone","document":"pers","multiple":true},{"enonce":"Pourquoi Ana n’est-elle pas chômeuse, alors qu’elle cherche un emploi ?","aide":"Regarde la condition « sans emploi ».","type":"choix","options":[{"id":"a","texte":"Elle n’est pas disponible pour travailler dans les deux semaines qui suivent"},{"id":"b","texte":"Elle n’est pas inscrite à France Travail, et le BIT exige cette inscription pour compter"},{"id":"c","texte":"Elle a travaillé au moins une heure durant la semaine de référence : elle est donc occupée"},{"id":"d","texte":"Elle suit une formation, et toute personne en formation est exclue des chômeurs"}],"multiple":false},{"enonce":"Quel est le taux de chômage de cette commune, en % ? Attention : il se rapporte à la population active.","aide":"Population active = actifs occupés + chômeurs.","type":"nombre","unite":"%"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r4c0"]},"explication":"**Bilal** et **Élise** remplissent les trois conditions. Ana a travaillé, Chloé ne cherche pas, Dylan n’est pas disponible."},{"cle":{"type":"choix","ids":["c"]},"explication":"Pour le BIT, **une seule heure** travaillée pendant la semaine de référence suffit pour être compté comme occupé."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 %","explication":"Population active = 4 500 + 500 = 5 000. Taux = 500 ÷ 5 000 = **10 %**. (Rapporté à la population totale, on aurait trouvé 5 %, ce qui est faux.)"}]$ex$::jsonb),
  ('be56bb0c-52c5-56b2-80d0-f7d19153f929'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux pays, même taux de chômage","competence":"lire-tableau","situation":"Deux pays imaginaires affichent le même taux de chômage. Leur situation est-elle pour autant identique ? Le tableau permet d’en juger.","documents":[{"id":"pays","type":"tableau","titre":"Deux pays imaginaires","source":"Chiffres imaginés pour l’exercice.","colonnes":["","Pays A","Pays B"],"lignes":[["Population en âge de travailler","10 000","10 000"],["Actifs occupés","6 650","4 750"],["Chômeurs","350","250"]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le taux de chômage du pays A, en % ?","aide":"Taux de chômage = chômeurs ÷ population active. La population active est la somme des actifs occupés et des chômeurs.","type":"nombre","unite":"%"},{"enonce":"Quel est le taux d’emploi du pays B, en % ?","aide":"Taux d’emploi = actifs occupés ÷ population en âge de travailler.","type":"nombre","unite":"%"},{"enonce":"Le taux de chômage se rapporte à la population ___ (un mot).","aide":"Elle comprend les actifs occupés et les chômeurs.","type":"texte"},{"enonce":"Que conclure de la comparaison des deux pays ?","aide":"Compare les taux d’emploi des deux pays.","type":"choix","options":[{"id":"a","texte":"Même taux de chômage, mais taux d’emploi très différents : il faut lire les deux indicateurs"},{"id":"b","texte":"Le pays B a proportionnellement moins de chômeurs que le pays A parmi ses actifs, donc il va mieux"},{"id":"c","texte":"Les deux pays ont exactement la même situation, puisque leur taux de chômage est identique"},{"id":"d","texte":"Le taux d’emploi ne dit rien de plus que le taux de chômage, il le répète seulement"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 %","explication":"Population active = 6 650 + 350 = 7 000. Taux = 350 ÷ 7 000 = **5 %**. Celui du pays B vaut aussi 5 %."},{"cle":{"type":"nombre","valeur":47.5,"tolerance":0},"affichage":"47,5 %","explication":"4 750 ÷ 10 000 = **47,5 %**. Dans le pays A, il vaut 66,5 %."},{"cle":{"type":"texte","acceptes":["active","la population active"]},"affichage":"active","explication":"Le taux de chômage se rapporte à la **population active**, jamais à la population totale."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les deux pays ont 5 % de chômage, mais **66,5 %** et **47,5 %** de taux d’emploi : ne regarder que le premier taux fait manquer la moitié de l’information."}]$ex$::jsonb),
  ('be56bb0c-52c5-56b2-80d0-f7d19153f929'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le taux baisse : bonne nouvelle ?","competence":"analyser-document","situation":"Un gouvernement imaginaire se réjouit de la baisse du taux de chômage. Deux documents permettent de vérifier si ce recul vient de créations d’emplois ou d’autre chose.","documents":[{"id":"trim","type":"tableau","titre":"Deux trimestres consécutifs","source":"Chiffres imaginés pour l’exercice.","colonnes":["","Trimestre 1","Trimestre 2"],"lignes":[["Actifs occupés","27 000","27 000"],["Chômeurs","3 000","2 250"],["Population en âge de travailler","45 000","45 000"]],"enteteLignes":true},{"id":"halo","type":"graphique","forme":"barres","titre":"Chômeurs et halo autour du chômage","source":"Chiffres imaginés pour l’exercice.","categories":["Trimestre 1","Trimestre 2"],"series":[{"nom":"Chômeurs","valeurs":[3000,2250],"teinte":"gris"},{"nom":"Halo autour du chômage","valeurs":[1000,1750],"teinte":"violet"}],"axeY":{"titre":"Personnes","min":0,"max":3500,"pas":500},"axeX":{"titre":"Trimestre"},"valeurs":false}],"questions":[{"enonce":"Quel est le taux de chômage au trimestre 1, en % ?","aide":"Taux = chômeurs ÷ (actifs occupés + chômeurs).","type":"nombre","unite":"%"},{"enonce":"Quel est le taux de chômage au trimestre 2, en % ? Arrondis au dixième.","aide":"Population active du trimestre 2 : 27 000 + 2 250.","type":"nombre","unite":"%"},{"enonce":"Touche la ligne qui montre qu’aucun emploi n’a été créé entre les deux trimestres.","aide":"Cherche la ligne qui est restée identique.","type":"zone","document":"trim","multiple":false},{"enonce":"De combien de personnes le halo autour du chômage a-t-il augmenté entre les deux trimestres ?","aide":"Soustrais la barre violette du trimestre 1 à celle du trimestre 2.","type":"nombre","unite":"personnes"},{"enonce":"Que peut-on conclure de ces deux documents ?","aide":"Les actifs occupés n’ont pas changé. Où sont passés les chômeurs en moins ?","type":"choix","options":[{"id":"a","texte":"Le chômage a baissé grâce à 750 créations d’emplois, qui ont absorbé une partie des chômeurs"},{"id":"b","texte":"Le halo autour du chômage est sans rapport avec la baisse du taux, qu’il n’explique pas"},{"id":"c","texte":"Le taux d’emploi a progressé fortement, ce qui montre une reprise solide de l’activité"},{"id":"d","texte":"Le taux de chômage baisse parce que des chômeurs ont cessé de chercher, non parce que l’emploi progresse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 %","explication":"3 000 ÷ (27 000 + 3 000) = **10 %**."},{"cle":{"type":"nombre","valeur":7.7,"tolerance":0.05},"affichage":"7,7 %","explication":"2 250 ÷ 29 250 ≈ **7,7 %**."},{"cle":{"type":"zone","ids":["r0c0"]},"explication":"Le nombre d’**actifs occupés** est resté à 27 000 : aucun emploi net n’a été créé."},{"cle":{"type":"nombre","valeur":750,"tolerance":0},"affichage":"750 personnes","explication":"1 750 − 1 000 = **750 personnes**, autant que la baisse du nombre de chômeurs."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les **750 chômeurs en moins** sont passés dans le **halo** : ils ont cessé de chercher. Le taux d’emploi reste à 27 000 ÷ 45 000 = 60 % : regarder le taux d’emploi permet de trancher."}]$ex$::jsonb),
  ('97f464e5-d7e5-5ccc-b22c-822050cd6699'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Deux diagnostics sur le chômage","competence":"analyser-document","situation":"Inès et Marc discutent des causes du chômage. Leurs avis reflètent les deux grandes familles d’explication du programme.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Inès","emoji":"👩","cote":"gauche"},{"nom":"Marc","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Les entreprises n’embauchent pas parce qu’elles ne vendent pas assez. Les chômeurs accepteraient le salaire actuel, mais aucun poste n’est ouvert."},{"qui":"Marc","texte":"Moi, je pense que le salaire minimum est trop haut : certains postes ne sont plus rentables, donc ils ne sont pas créés."}]}],"questions":[{"enonce":"Associe chaque personne à l’explication qu’elle donne.","aide":"Inès parle des ventes, Marc du coût du travail.","type":"association","gauche":[{"id":"g0","texte":"Inès"},{"id":"g1","texte":"Marc"}],"droite":[{"id":"d0","texte":"Salaire réel au-dessus du niveau d’équilibre"},{"id":"d1","texte":"Insuffisance de la demande"}]},{"enonce":"Range chaque mesure selon la famille d’explication dont elle découle.","aide":"Soutenir la demande, c’est faire dépenser ; assouplir, c’est réduire le coût ou les règles.","type":"categories","categories":[{"id":"c0","texte":"Soutenir la demande"},{"id":"c1","texte":"Assouplir le marché du travail"}],"items":[{"id":"i0","texte":"Baisse des taux directeurs"},{"id":"i1","texte":"Baisse d’impôts pour les ménages"},{"id":"i2","texte":"Assouplissement de la protection de l’emploi"},{"id":"i3","texte":"Baisse des cotisations sociales"},{"id":"i4","texte":"Relance par la dépense publique"},{"id":"i5","texte":"Réforme de l’indemnisation du chômage"}]},{"enonce":"Inès décrit un cercle vicieux. Remets ses maillons dans l’ordre.","aide":"La boucle repart de la demande qui manque aux entreprises.","type":"ordre","items":[{"id":"a","texte":"Moins de consommation, donc moins de demande adressée aux entreprises"},{"id":"b","texte":"Moins de salariés, donc moins de revenus"},{"id":"c","texte":"Les entreprises vendent moins et embauchent moins"},{"id":"d","texte":"Moins de revenus, donc moins de consommation"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1"}},"explication":"Inès adopte une lecture **keynésienne** (manque de demande), Marc une lecture **néoclassique** (salaire trop élevé)."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c1"}},"explication":"Les mesures de **demande** font dépenser (dépense publique, taux, impôts). Les mesures d’**offre** réduisent le coût ou les règles du marché du travail."},{"cle":{"type":"ordre","ids":["c","b","d","a"]},"explication":"Le mécanisme **s’auto-entretient** : moins d’emploi, moins de revenu, moins de consommation, moins de demande, donc moins d’emploi."}]$ex$::jsonb),
  ('97f464e5-d7e5-5ccc-b22c-822050cd6699'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Payer plus que le marché, par choix","competence":"modeliser","situation":"Une entreprise imaginaire de 100 salariés hésite à verser un salaire plus élevé que celui du marché. Elle veut réduire les départs, qui lui coûtent cher en recrutement et en formation.","documents":[{"id":"salaire","type":"tableau","titre":"Deux politiques salariales","source":"Entreprise et chiffres imaginés pour l’exercice.","colonnes":["","Salaire du marché","Salaire supérieur"],"lignes":[["Salaire mensuel (€)","1 600","1 700"],["Départs par an (pour 100 salariés)",40,10],["Coût d’un départ (€)","6 000","6 000"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne le nombre de départs avec le salaire supérieur.","aide":"Cherche la ligne des départs, colonne du salaire supérieur.","type":"zone","document":"salaire","multiple":false},{"enonce":"Combien l’entreprise économise-t-elle par an sur les coûts de départ avec le salaire supérieur, en euros ?","aide":"Coût des départs au salaire du marché : 40 × 6 000. Au salaire supérieur : 10 × 6 000.","type":"nombre","unite":"€"},{"enonce":"Combien lui coûte, par an, la hausse de 100 € par mois pour ses 100 salariés, en euros ?","aide":"100 € × 12 mois × 100 salariés.","type":"nombre","unite":"€"},{"enonce":"Quel est le gain net annuel de l’entreprise, en euros ?","aide":"Gain net = économie sur les départs − surcoût des salaires.","type":"nombre","unite":"€"},{"enonce":"Que montre cet exemple pour le débat sur le chômage ?","aide":"Personne n’oblige l’entreprise à payer 1 700 €.","type":"choix","options":[{"id":"a","texte":"Le chômage vient toujours du salaire minimum, qui empêche les salaires de baisser"},{"id":"b","texte":"Les départs n’ont aucun coût pour l’entreprise, qui remplace facilement ses salariés"},{"id":"c","texte":"Une entreprise peut payer au-dessus du marché par choix : c’est le salaire d’efficience"},{"id":"d","texte":"Les entreprises ne paient jamais plus que le marché, car cela réduirait leurs profits"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Avec le salaire supérieur, il y a **10 départs** par an."},{"cle":{"type":"nombre","valeur":180000,"tolerance":0},"affichage":"180 000 €","explication":"240 000 − 60 000 = **180 000 €** d’économie par an."},{"cle":{"type":"nombre","valeur":120000,"tolerance":0},"affichage":"120 000 €","explication":"100 × 12 × 100 = **120 000 €** par an."},{"cle":{"type":"nombre","valeur":60000,"tolerance":0},"affichage":"60 000 €","explication":"180 000 − 120 000 = **60 000 €** par an."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le **salaire d’efficience** est choisi volontairement par l’entreprise : il maintient des salaires au-dessus de l’équilibre et un chômage durable **sans rigidité imposée**."}]$ex$::jsonb),
  ('97f464e5-d7e5-5ccc-b22c-822050cd6699'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le chômage qui s’installe","competence":"raisonner","situation":"Dans un pays imaginaire, le taux de chômage monte pendant une récession, puis ne retrouve pas son niveau d’avant. Un graphique et un témoignage aident à comprendre pourquoi.","documents":[{"id":"chom","type":"graphique","forme":"courbe","titre":"Taux de chômage d’un pays imaginaire","source":"Données imaginées pour l’exercice.","categories":["2007","2008","2009","2010","2011","2012","2013","2014"],"series":[{"nom":"Taux de chômage","valeurs":[6,6,9,10,9.5,9,9,9],"teinte":"violet"}],"axeY":{"titre":"Taux de chômage","unite":"en %","min":0,"max":12,"pas":2},"axeX":{"titre":"Année"}},{"id":"temoin","type":"texte","genre":"article","titre":"Le témoignage de Théo","auteur":"Texte écrit pour l’exercice","blocs":["Théo, 45 ans, a perdu son emploi d’opérateur en 2009. En 2012, il n’a toujours pas retrouvé de poste.","« Je ne connais plus les nouvelles machines, dit-il. Et aux entretiens, on me demande ce que j’ai fait pendant trois ans. »"]}],"questions":[{"enonce":"Touche l’année où le chômage atteint son point le plus haut.","aide":"Cherche le sommet de la courbe.","type":"zone","document":"chom","multiple":false},{"enonce":"De combien de points le taux de chômage de 2014 dépasse-t-il celui de 2007 ?","aide":"Soustrais le taux de 2007 à celui de 2014.","type":"nombre","unite":"points"},{"enonce":"Touche le mot qui illustre la dégradation des compétences de Théo.","aide":"Cherche ce que Théo dit ne plus connaître.","type":"zone","document":"temoin","multiple":false},{"enonce":"Complète la phrase qui définit l’hystérésis.","aide":"L’hystérésis transforme un chômage lié à la récession en chômage durable.","type":"trous","segments":["Un chômage ",0," long finit par devenir ",1,"."],"banque":["conjoncturel","frictionnel","volontaire","structurel"]},{"enonce":"Quelle conséquence de politique économique en tire-t-on ?","aide":"Que se passe-t-il si l’on attend trop longtemps ?","type":"choix","options":[{"id":"a","texte":"Attendre que le chômage baisse tout seul, car il finit toujours par se résorber"},{"id":"b","texte":"Réagir vite aux récessions, car attendre a un coût qui devient permanent pour l’économie"},{"id":"c","texte":"Ne rien faire en récession, car toute intervention de l’État aggrave la crise"},{"id":"d","texte":"Supprimer tout soutien aux chômeurs, afin de les inciter à reprendre un emploi"}],"multiple":false}]}$ex$::jsonb,
