   $ex${"titre":"Tous bacheliers, pas tous au même endroit","competence":"analyser-document","situation":"Dans une académie imaginaire, on a relevé le type de baccalauréat obtenu par 100 bacheliers enfants de cadres et 100 bacheliers enfants d’ouvriers.","documents":[{"id":"types","type":"tableau","titre":"Type de baccalauréat obtenu (pour 100 bacheliers de chaque origine)","source":"Chiffres imaginés pour l’exercice, dans le sens des écarts observés.","colonnes":["Origine sociale","Bac général","Bac technologique","Bac professionnel"],"lignes":[["Enfants de cadres",75,15,10],["Enfants d’ouvriers",40,22,38]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case de la part d’enfants d’ouvriers qui obtiennent un bac professionnel.","aide":"Repère la ligne « ouvriers » puis la colonne « professionnel ».","type":"zone","document":"types","multiple":false},{"enonce":"De combien de points de pourcentage la part du bac général diffère-t-elle entre enfants de cadres et enfants d’ouvriers ?","aide":"Soustrais les deux parts de la colonne « Bac général ».","type":"nombre","unite":"points"},{"enonce":"Quelle interprétation est correcte ?","aide":"Le tableau compte les bacheliers, pas les échecs.","type":"choix","options":[{"id":"a","texte":"L’origine sociale n’a plus aucune influence sur le type de baccalauréat obtenu en fin de lycée"},{"id":"b","texte":"Le bac professionnel est devenu la filière la plus prestigieuse pour les enfants de cadres"},{"id":"c","texte":"Tous accèdent au bac, mais les enfants de cadres se dirigent davantage vers les filières les plus valorisées"},{"id":"d","texte":"Les enfants d’ouvriers échouent plus souvent au bac que les enfants de cadres dans toutes les séries"}],"multiple":false},{"enonce":"Associe chaque situation à la notion qu’elle illustre.","aide":"Quatre notions, à ne pas confondre.","type":"association","gauche":[{"id":"g0","texte":"Le nombre de bacheliers a été multiplié par seize"},{"id":"g1","texte":"L’écart d’accès au supérieur