  ('b7f2e795-433c-5a20-a828-25c14ef6018b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Plus diplômée que son père","competence":"analyser-document","situation":"Chloé, 24 ans, est la première de sa famille à avoir un master. Son père, titulaire d’un CAP, est devenu contremaître. Un tableau imaginaire montre comment le marché a évolué.","documents":[{"id":"flux","type":"tableau","titre":"Jeunes diplômés du supérieur et emplois qualifiés proposés, par an (milliers)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","1990","2020"],"lignes":[["Jeunes diplômés du supérieur",100,250],["Emplois qualifiés proposés aux jeunes",100,150]],"enteteLignes":true},{"id":"dial","type":"dialogue","modele":"sms","participants":[{"nom":"Chloé","emoji":"👩","cote":"gauche"},{"nom":"Yanis","emoji":"🧑","cote":"droite"}],"repliques":[{"qui":"Yanis","texte":"Tu as un master, ton père avait un CAP. Tu es bien mieux placée que lui !"},{"qui":"Chloé","texte":"Pas vraiment : je suis conseillère clientèle, et lui est devenu contremaître à 30 ans."}]}],"questions":[{"enonce":"Touche la case du nombre d’emplois qualifiés proposés en 2020.","aide":"Choisis la ligne des emplois, puis la colonne 2020.","type":"zone","document":"flux","multiple":false},{"enonce":"De combien, en %, le nombre de jeunes diplômés a-t-il augmenté entre 1990 et 2020 ?","aide":"(250 − 100) ÷ 100 × 100.","type":"nombre","unite":"%"},{"enonce":"En 2020, combien de jeunes diplômés (en milliers) n’ont pas d’emploi qualifié proposé à leur niveau ?","aide":"Soustrais les emplois aux diplômés.","type":"nombre","unite":"milliers"},{"enonce":"Quelle notion le dialogue illustre-t-il le mieux ?","aide":"Compare le diplôme et la position de Chloé avec ceux de son père.","type":"choix","options":[{"id":"a","texte":"La solidarité organique : Chloé complète désormais les fonctions exercées par son père"},{"id":"b","texte":"Le paradoxe d’Anderson : être plus diplômé que son père ne garantit plus une meilleure position"},{"id":"c","texte":"La démocratisation : Chloé a profité de l’ouverture des filières à tous les milieux sociaux"},{"id":"d","texte":"La moyennisation : Chloé et son père appartiennent désormais à la même classe moyenne"}],"multiple":false}]}$ex$::jsonb,
