   $ex${"titre":"Même niveau, autre orientation","competence":"analyser-document","situation":"À la fin de la 3e, des élèves imaginaires de même niveau scolaire demandent ou non la seconde générale et technologique. On compare leur origine sociale.","documents":[{"id":"orient","type":"tableau","titre":"Demandes de seconde générale et technologique (élèves de même niveau)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Origine","Élèves","Demandent une 2de générale et technologique"],"lignes":[["Enfants de cadres",100,90],["Enfants d’ouvriers",100,60]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la demande de 2de générale des enfants d’ouvriers.","aide":"Lis la ligne « ouvriers ».","type":"zone","document":"orient","multiple":false},{"enonce":"De combien de points de pourcentage l’écart de demande entre les deux origines s’élève-t-il ?","aide":"Soustrais 60 à 90.","type":"nombre","unite":"points"},{"enonce":"Complète le raisonnement.","aide":"Pense à la logique de Boudon.","type":"trous","segments":["À résultats identiques, la famille compare le ",0,", le risque d’échec et le bénéfice attendu des études longues. Ces termes pèsent plus lourd en milieu ",1,"."],"banque":["profit","modeste","coût","favorisé","public"]},{"enonce":"Ce tableau compare des élèves de même niveau. Quelle explication s’applique le mieux ?","aide":"Le niveau scolaire étant identique, ce ne sont pas les notes qui diffèrent.","type":"choix","options":[{"id":"a","texte":"La carte scolaire : les enfants d’ouvriers sont tous scolarisés dans des établissements plus difficiles"},{"id":"b","texte":"Le capital culturel : les élèves favorisés ont de meilleures notes grâce à la culture de leur famille"},{"id":"c","texte":"Les stratégies familiales : à résultats égaux, le coût et le risque des études longues ne pèsent pas pareil"},{"id":"d","texte":"L’effet Pygmalion : les enseignants attendent moins des élèves d’origine modeste et les notent plus durement"}],"multiple":false}]}$ex$::jsonb,
