   $ex${"titre":"Trois mesures, trois égalités","competence":"analyser-document","situation":"Une ville imaginaire étudie trois mesures pour lutter contre les inégalités. Chacune repose sur une conception différente de l’égalité.","documents":[{"id":"mesures","type":"tableau","titre":"Trois mesures envisagées","source":"Mesures imaginées pour l’exercice.","colonnes":["Mesure","Contenu"],"lignes":[["Mesure 1","Interdire à un employeur de refuser un CV à cause du nom du candidat"],["Mesure 2","Offrir du soutien scolaire gratuit aux élèves des quartiers défavorisés"],["Mesure 3","Verser une aide plus élevée aux ménages modestes pour réduire l’écart des niveaux de vie"]],"enteteLignes":true}],"questions":[{"enonce":"Associe chaque mesure à la conception de l’égalité qu’elle met en œuvre.","aide":"Droits : mêmes règles. Chances : mêmes possibilités au départ. Situations : réduire l’écart lui-même.","type":"association","gauche":[{"id":"g0","texte":"Interdire de refuser un CV à cause du nom"},{"id":"g1","texte":"Soutien scolaire gratuit en quartier défavorisé"},{"id":"g2","texte":"Aide plus élevée pour réduire l’écart des niveaux de vie"}],"droite":[{"id":"d0","texte":"Égalité des chances"},{"id":"d1","texte":"Égalité des situations"},{"id":"d2","texte":"Égalité des droits"}]},{"enonce":"Touche la mesure qui traite différemment certains élèves pour leur donner les mêmes possibilités.","aide":"Qui bénéficie du soutien gratuit ?","type":"zone","document":"mesures","multiple":false},{"enonce":"Pourquoi l’égalité des chances peut-elle heurter l’égalité stricte des droits ?","aide":"Traiter tout le monde pareil donne-t-il les mêmes possibilités ?","type":"choix","options":[{"id":"a","texte":"Elle refuse que des règles soient appliquées de la même façon aux élèves et aux adultes"},{"id":"b","texte":"Elle interdit à l’État de mener toute politique de redistribution des revenus"},{"id":"c","texte":"Elle suppose de traiter différemment des personnes pour leur donner des possibilités comparables"},{"id":"d","texte":"Elle exige que tous les individus obtiennent exactement le même revenu à la fin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Droits** : les mêmes règles pour tous. **Chances** : les mêmes possibilités au départ. **Situations** : réduire l’écart lui-même."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"La **mesure 2** réserve un soutien à certains élèves : c’est un traitement différencié au service de l’égalité des chances."},{"cle":{"type":"choix","ids":["c"]},"explication":"Donner les mêmes possibilités suppose des traitements **différenciés** (discrimination positive) : cela heurte l’égalité stricte des droits."}]$ex$::jsonb),
  ('775fcb8d-e304-51b1-badb-a9dbe8f35df2'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre juges d’une même réforme","competence":"argumenter","situation":"Dans une société imaginaire de deux ménages, une réforme augmente les revenus de tous, mais pas dans les mêmes proportions. Quatre conceptions de la justice la jugent.","documents":[{"id":"reforme","type":"tableau","titre":"Revenus avant et après la réforme (€ par mois)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Ménage","Avant","Après"],"lignes":[["Ménage modeste",1000,1100],["Ménage aisé",4000,4500]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne le revenu du ménage le plus défavorisé après la réforme.","aide":"Le plus défavorisé est le ménage modeste.","type":"zone","document":"reforme","multiple":false},{"enonce":"Quel est l’écart de revenu entre les deux ménages après la réforme, en euros ?","aide":"Soustrais 1 100 à 4 500.","type":"nombre","unite":"€"},{"enonce":"De combien le revenu total des deux ménages a-t-il augmenté, en euros ?","aide":"Additionne les deux gains : 100 € et 500 €.","type":"nombre","unite":"€"},{"enonce":"Associe chaque conception de la justice à son verdict sur la réforme.","aide":"Chaque auteur a son critère : plus défavorisés, total, écart, processus.","type":"association","gauche":[{"id":"g0","texte":"Rawls (principe de différence)"},{"id":"g1","texte":"Bentham (utilitarisme)"},{"id":"g2","texte":"Égalité des situations"},{"id":"g3","texte":"Nozick (libertarisme)"}],"droite":[{"id":"d0","texte":"Injuste : l’écart passe de 3 000 à 3 400 €"},{"id":"d1","texte":"Juste : le revenu total augmente de 600 €"},{"id":"d2","texte":"Juste : les plus modestes y gagnent 100 €"},{"id":"d3","texte":"Juste si ces revenus viennent d’échanges libres et légitimes"}]}]}$ex$::jsonb,
