id":"i3","texte":"Allocation chômage financée par cotisations"},{"id":"i4","texte":"Minimum vieillesse"}]},{"enonce":"Pourquoi le non-recours pose-t-il un problème de justice sociale ?","aide":"Une aide prévue mais non reçue atteint-elle son but ?","type":"choix","options":[{"id":"a","texte":"Des personnes ayant droit à l’aide ne la reçoivent pas : l’objectif de la prestation n’est pas atteint"},{"id":"b","texte":"Les personnes qui perçoivent la prestation sont trop nombreuses pour le budget prévu"},{"id":"c","texte":"La prestation fait perdre l’envie de travailler à ceux qui en bénéficient et la perçoivent"},{"id":"d","texte":"La prestation est versée à des personnes qui n’y ont pas droit en raison de contrôles insuffisants"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":35,"tolerance":0},"affichage":"35 %","explication":"(10 000 − 6 500) ÷ 10 000 = **35 %**."},{"cle":{"type":"nombre","valeur":12.6,"tolerance":0.05},"affichage":"12,6 millions €","explication":"3 500 × 300 × 12 = 12 600 000, soit **12,6 millions d’euros** par an."},{"cle":{"type":"zone","ids":["m15"]},"explication":"Les **formulaires** trop longs découragent : c’est la complexité des droits."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1"}},"explication":"L’**assurance** repose sur des cotisations ; l’**assistance** sur un besoin constaté, sans cotisation préalable."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le **non-recours** laisse une part des ayants droit sans aide : la justice sociale visée n’est pas atteinte."}]$ex$::jsonb),
  ('9e114fd7-8be1-5f21-9f50-8ae7bc9344cc'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le CDI, norme ou ticket d’entrée ?","competence":"lire-graphique","situation":"Le CDI reste la forme d’emploi la plus répandue. Mais regarde-t-on la même chose quand on compte les emplois existants et quand on compte les embauches ?","documents":[{"id":"cdi","type":"graphique","forme":"barres","titre":"Le CDI dans l’emploi et dans les embauches (%)","source":"Ordres de grandeur arrondis, France.","categories":["Part de l’emploi total","Part des embauches"],"series":[{"nom":"CDI","valeurs":[75,13],"teinte":"violet"},{"nom":"Autres formes particulières","valeurs":[13,87],"teinte":"ambre"}],"axeY":{"titre":"Part","unite":"en %","min":0,"max":100,"pas":20},"axeX":{"titre":"Type de mesure"}}],"questions":[{"enonce":"Touche la mesure pour laquelle le CDI est le moins présent.","aide":"Compare la hauteur de la barre de CDI dans chaque groupe.","type":"zone","document":"cdi","multiple":false},{"enonce":"Sur 1 000 embauches, combien sont des CDI, environ ? (utilise 13 %)","aide":"Calcule 13 % de 1 000.","type":"nombre","unite":"embauches"},{"enonce":"Comment concilier les deux barres ?","aide":"Un stock et un flux ne se comptent pas de la même façon.","type":"choix","options":[{"id":"a","texte":"Les embauches en CDI sont plus nombreuses que les embauches en contrat court, selon le graphique"},{"id":"b","texte":"Le CDI a disparu du marché du travail : il ne représente plus qu’un emploi sur huit"},{"id":"c","texte":"Les formes particulières dominent parmi les emplois existants comme parmi les embauches"},{"id":"d","texte":"Le CDI domine parmi les emplois existants mais n’est plus la porte d’entrée dans l’emploi"}],"multiple":false},{"enonce":"Complète le raisonnement.","aide":"Pense à ce que l’on obtient après plusieurs contrats courts.","type":"trous","segments":["Le CDI est devenu une position à ",0," , non un point de ",1,"."],"banque":["quitter","fuir","départ","arrivée","atteindre"]}]}$ex$::jsonb,
