  ('9e114fd7-8be1-5f21-9f50-8ae7bc9344cc'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un sablier de qualifications","competence":"analyser-document","situation":"Dans un pays imaginaire, on répartit les emplois en trois groupes selon la qualification. Le tableau compare 1990 et 2020.","documents":[{"id":"pola","type":"tableau","titre":"Répartition des emplois (% du total)","source":"Chiffres imaginés pour l’exercice, dans le sens des évolutions observées.","colonnes":["Groupe d’emplois","1990","2020"],"lignes":[["Très qualifiés",25,33],["Qualification intermédiaire",50,37],["Peu qualifiés (services)",25,30]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne du groupe dont la part recule.","aide":"Cherche le groupe dont le pourcentage diminue.","type":"zone","document":"pola","multiple":false},{"enonce":"De combien de points de pourcentage la part des emplois intermédiaires a-t-elle évolué ? Donne un nombre négatif.","aide":"Soustrais 50 à 37.","type":"nombre","unite":"points"},{"enonce":"De combien, en %, la part des emplois très qualifiés a-t-elle augmenté ?","aide":"(33 − 25) ÷ 25 × 100.","type":"nombre","unite":"%"},{"enonce":"Range chaque emploi selon sa place dans la polarisation.","aide":"Au milieu : emplois routiniers, exposés à l’automatisation.","type":"categories","categories":[{"id":"c0","texte":"En haut"},{"id":"c1","texte":"Au milieu"},{"id":"c2","texte":"En bas"}],"items":[{"id":"i0","texte":"Employée de saisie comptable"},{"id":"i1","texte":"Ingénieure en intelligence artificielle"},{"id":"i2","texte":"Livreur à vélo"},{"id":"i3","texte":"Aide à domicile"},{"id":"i4","texte":"Médecin hospitalier"},{"id":"i5","texte":"Technicien de maintenance en usine"}]},{"enonce":"Pourquoi les emplois peu qualifiés de services progressent-ils ?","aide":"Pense à ce qu’un robot ne sait pas faire.","type":"choix","options":[{"id":"a","texte":"Ils ont été créés pour remplacer les emplois qualifiés supprimés dans les bureaux"},{"id":"b","texte":"Ils bénéficient d’un contrat de travail plus protecteur que les emplois intermédiaires"},{"id":"c","texte":"Ils sont très bien rémunérés, ce qui attire de plus en plus de diplômés du supérieur"},{"id":"d","texte":"Ils sont difficilement automatisables et répondent à une demande locale en hausse"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"Seule la part des emplois de **qualification intermédiaire** recule, de 50 à 37 %."},{"cle":{"type":"nombre","valeur":-13,"tolerance":0},"affichage":"−13 points","explication":"37 − 50 = **− 13 points**."},{"cle":{"type":"nombre","valeur":32,"tolerance":0},"affichage":"32 %","explication":"(33 − 25) ÷ 25 = 0,32, soit **+ 32 %**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c2","i3":"c2","i4":"c0","i5":"c1"}},"explication":"**En haut** : très qualifiés ; **au milieu** : routiniers, exposés à l’automatisation ; **en bas** : services difficilement automatisables."},{"cle":{"type":"choix","ids":["d"]},"explication":"Aide à domicile, livraison, nettoyage : des tâches **peu automatisables** et toujours demandées."}]$ex$::jsonb),
  ('9e114fd7-8be1-5f21-9f50-8ae7bc9344cc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Indépendant sur le papier","competence":"analyser-document","situation":"Sami livre des repas pour une plateforme. Il est inscrit comme travailleur indépendant. Il raconte son quotidien, puis on calcule ce qu’il gagne.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Sami","emoji":"🚴","cote":"gauche"},{"nom":"Lou","emoji":"👩","cote":"droite"}],"repliques":[{"qui":"Lou","texte":"Tu es ton propre patron, non ?"},{"qui":"Sami","texte":"Je choisis mes horaires, mais l’appli fixe le prix des courses et me désactive si j’en refuse trop."}]},{"id":"revenu","type":"tableau","titre":"Une semaine de Sami","source":"Chiffres imaginés pour l’exercice.","colonnes":["Poste","Valeur"],"lignes":[["Heures de travail",40],["Courses par heure",2],["Prix d’une course (€)",5],["Cotisations et frais de la plateforme (% du chiffre d’affaires)","30 %"],["Carburant et entretien (€ par heure)",1]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que la plateforme sanctionne le livreur.","aide":"Cherche ce que fait l’appli quand il refuse des courses.","type":"zone","document":"sms","multiple":false},{"enonce":"Quel est le chiffre d’affaires de Sami sur la semaine, en euros ?","aide":"Heures × courses par heure × prix d’une course.","type":"nombre","unite":"€"},{"enonce":"Après les cotisations (30 %) et le carburant (1 € par heure), quel est son revenu net par heure, en euros ?","aide":"400 − 120 − 40, puis divise par 40.","type":"nombre","unite":"€"},{"enonce":"Range chaque élément selon ce qu’il indique.","aide":"Indépendance : liberté de décider. Subordination : décisions imposées.","type":"categories","categories":[{"id":"c0","texte":"Signe d’indépendance"},{"id":"c1","texte":"Signe de subordination économique"}],"items":[{"id":"i0","texte":"Il choisit ses horaires de connexion"},{"id":"i1","texte":"L’appli le désactive s’il refuse des courses"},{"id":"i2","texte":"Le prix de la course est fixé par l’appli"},{"id":"i3","texte":"Il est noté par les clients, ce qui conditionne ses commandes"},{"id":"i4","texte":"Il possède son propre vélo"}]},{"enonce":"Que risque la plateforme devant un tribunal ?","aide":"Plusieurs décisions de justice se sont déjà prononcées sur ce point.","type":"choix","options":[{"id":"a","texte":"Une interdiction définitive de proposer des livraisons à tous les livreurs indépendants"},{"id":"b","texte":"Une suppression automatique de la note donnée par les clients à chaque livreur"},{"id":"c","texte":"Une obligation de faire signer un CDI à tous les livreurs de moins de 25 ans"},{"id":"d","texte":"Une requalification de la relation en contrat de travail, si la subordination est établie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m20"]},"explication":"« **désactive** » : la plateforme exerce un pouvoir de sanction, signe de subordination."},{"cle":{"type":"nombre","valeur":400,"tolerance":0},"affichage":"400 €","explication":"40 × 2 × 5 = **400 €**."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6 €","explication":"(400 − 120 − 40) ÷ 40 = **6 € par heure**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Le livreur est **juridiquement indépendant** mais **économiquement subordonné** : tarifs, sanctions et notation sont imposés."},{"cle":{"type":"choix","ids":["d"]},"explication":"Plusieurs décisions de justice ont **requalifié** ces relations en contrat de travail quand la subordination était établie."}]$ex$::jsonb),
  ('15c2d400-26d0-572b-99a7-60d260fb2102'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Décomposer un geste, à la Taylor","competence":"modeliser","situation":"Dans un atelier imaginaire, un ouvrier monte un boîtier en cinq gestes. On chronomètre chaque geste pour organiser le travail comme le propose Taylor.","documents":[{"id":"gestes","type":"tableau","titre":"Le montage d’un boîtier","source":"Chronométrage imaginé pour l’exercice.","colonnes":["Geste","Durée (s)"],"lignes":[["Saisir le boîtier",12],["Poser la carte",8],["Visser (4 vis)",15],["Clipser le couvercle",5],["Coller l’étiquette",10]],"enteteLignes":true}],"questions":[{"enonce":"Touche le geste qui fixe la cadence d’une chaîne où chaque ouvrier répète un seul geste.","aide":"Sur une chaîne, on avance au rythme du poste le plus lent.","type":"zone","document":"gestes","multiple":false},{"enonce":"Combien de boîtiers un ouvrier qui fait les cinq gestes monte-t-il en une heure ?","aide":"Additionne les durées, puis divise 3 600 s par le total.","type":"nombre","unite":"boîtiers"},{"enonce":"Sur une chaîne de cinq ouvriers, un geste chacun, combien de boîtiers sortent en une heure ? (un boîtier toutes les 15 s)","aide":"Divise 3 600 s par 15 s.","type":"nombre","unite":"boîtiers"},{"enonce":"Découper le montage en gestes simples est un exemple de…","aide":"Il s’agit de découper les tâches, pas de séparer concevoir et exécuter.","type":"choix","options":[{"id":"a","texte":"Division verticale du travail, entre ceux qui conçoivent et ceux qui exécutent"},{"id":"b","texte":"Kaizen, où les suggestions des opérateurs améliorent peu à peu la production"},{"id":"c","texte":"Division horizontale du travail, en tâches élémentaires, répétitives et chronométrées"},{"id":"d","texte":"Juste-à-temps, où l’on produit seulement ce que les clients ont commandé"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"« Visser » dure **15 s** : c’est le geste le plus long, il impose le rythme à la chaîne."},{"cle":{"type":"nombre","valeur":72,"tolerance":0},"affichage":"72 boîtiers","explication":"Un boîtier demande 50 s : 3 600 ÷ 50 = **72 boîtiers**."},{"cle":{"type":"nombre","valeur":240,"tolerance":0},"affichage":"240 boîtiers","explication":"3 600 ÷ 15 = **240 boîtiers** : la productivité est multipliée par plus de trois."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est la **division horizontale** de Taylor. La division **verticale**, elle, sépare la conception (bureau des méthodes) de l’exécution."}]$ex$::jsonb),
  ('15c2d400-26d0-572b-99a7-60d260fb2102'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux usines, deux modèles","competence":"analyser-document","situation":"Deux usines imaginaires fabriquent le même appareil. L’une est organisée selon le modèle taylorien-fordiste, l’autre selon le modèle toyotiste. Un tableau les compare.","documents":[{"id":"usines","type":"tableau","titre":"Usine A et usine B","source":"Chiffres imaginés pour l’exercice.","colonnes":["Critère","Usine A","Usine B"],"lignes":[["Stock moyen de pièces","21 jours","1 jour"],["Contrôle de la qualité","En fin de chaîne, par des contrôleurs","À son poste, par l’opérateur"],["Postes tenus par un ouvrier","1","4"],["Suggestions d’amélioration par ouvrier et par an","0","12"],["Produits","Un seul modèle","Dix variantes"]],"enteteLignes":true}],"questions":[{"enonce":"Le stock de l’usine A représente combien de fois celui de l’usine B ?","aide":"Divise 21 jours par 1 jour.","type":"nombre","unite":"fois"},{"enonce":"Touche la case qui renvoie au kaizen (amélioration continue par les opérateurs).","aide":"Le kaizen repose sur les idées venues des opérateurs.","type":"zone","document":"usines","multiple":false},{"enonce":"Laquelle de ces deux usines produit à la commande, et à quoi le voit-on ?","aide":"Un gros stock signifie qu’on produit avant d’avoir vendu.","type":"choix","options":[{"id":"a","texte":"L’usine B : un stock d’un jour seulement signifie qu’elle produit au fil des commandes"},{"id":"b","texte":"L’usine A : un seul modèle signifie qu’elle ne produit que sur commande précise"},{"id":"c","texte":"L’usine A : un stock de 21 jours prouve qu’elle ajuste sa production à chaque commande"},{"id":"d","texte":"L’usine B : ses dix variantes prouvent qu’elle fabrique sans jamais regarder la demande"}],"multiple":false},{"enonce":"Associe chaque organisation à sa marque de fabrique.","aide":"Chaque modèle a ses inventeurs et ses pratiques.","type":"association","gauche":[{"id":"g0","texte":"Taylor"},{"id":"g1","texte":"Ford"},{"id":"g2","texte":"Ohno (Toyota)"},{"id":"g3",