   $ex${"titre":"Forte demande, faible latitude","competence":"raisonner","situation":"Un entrepôt imaginaire passe au juste-à-temps et à un suivi chronométré des préparateurs de commandes. La direction se félicite : la productivité monte. Le médecin du travail s’inquiète.","documents":[{"id":"postes","type":"tableau","titre":"Trois postes imaginaires","source":"Situations imaginées pour l’exercice.","colonnes":["Poste","Demande psychologique","Latitude décisionnelle"],"lignes":[["Préparateur de commandes chronométré","Forte","Faible"],["Conceptrice d’outils internes","Forte","Forte"],["Gardienne d’un site peu fréquenté","Faible","Faible"]],"enteteLignes":true},{"id":"ent","type":"tableau","titre":"Avant et après le juste-à-temps","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Avant","Après"],"lignes":[["Colis préparés par heure",30,40],["Temps d’attente entre deux colis (s)",40,10]],"enteteLignes":true}],"questions":[{"enonce":"Touche le poste où le modèle de Karasek prévoit le risque de souffrance le plus élevé.","aide":"La souffrance naît d’une forte demande et d’une faible latitude.","type":"zone","document":"postes","multiple":false},{"enonce":"De combien, en %, le nombre de colis par heure a-t-il augmenté ? (arrondi à l’unité)","aide":"(40 − 30) ÷ 30 × 100.","type":"nombre","unite":"%"},{"enonce":"Combien de secondes disposent désormais les préparateurs pour chaque colis ?","aide":"Divise 3 600 s par 40 colis.","type":"nombre","unite":"s"},{"enonce":"Que montre la baisse du temps d’attente entre deux colis, de 40 s à 10 s ?","aide":"Que devient la pause quand on supprime les temps d’attente ?","type":"choix","options":[{"id":"a","texte":"Les temps morts qui servaient de respiration ont disparu : le travail est plus intense"},{"id":"b","texte":"Le travail est devenu plus autonome, puisque les préparateurs choisissent leur rythme"},{"id":"c","texte":"Le travail est devenu moins intense, puisque les colis sont préparés plus vite"},{"id":"d","texte":"Le travail est redevenu taylorien, puisque chaque geste a été décomposé en gestes simples"}],"multiple":false},{"enonce":"Quelle conclusion de copie est la plus rigoureuse ?","aide":"Relie productivité, intensité et latitude.","type":"choix","options":[{"id":"a","texte":"Le modèle de Karasek ne s’applique pas aux entrepôts, seulement aux bureaux d’études"},{"id":"b","texte":"Le gain de productivité est sans conséquence sur la santé, tant que le salaire augmente"},{"id":"c","texte":"Le juste-à-temps améliore toujours la santé au travail, car il supprime la fatigue liée aux stocks"},{"id":"d","texte":"Le gain de productivité se paie d’une intensité accrue, d’où un risque pour la santé sans marge de décision"}],"multiple":false}]}$ex$::jsonb,
