  ('fe7bacb2-6584-59ec-be90-866c78b5ce8c'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Deux villes, deux solidarités","competence":"analyser-document","situation":"Durkheim oppose deux formes de solidarité. Un tableau imaginaire compare un village de 1850 et une ville de 2020.","documents":[{"id":"villes","type":"tableau","titre":"Saint-Aubin (1850) et Corbeil (2020)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Saint-Aubin (1850)","Corbeil (2020)"],"lignes":[["Part des habitants qui vivent de l’agriculture","90 %","2 %"],["Nombre de métiers différents recensés",8,310]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui montre la division du travail la plus poussée.","aide":"Plus il y a de métiers différents, plus le travail est divisé.","type":"zone","document":"villes","multiple":false},{"enonce":"Combien de fois plus de métiers y a-t-il à Corbeil qu’à Saint-Aubin ? (arrondi à l’unité)","aide":"Divise 310 par 8.","type":"nombre","unite":"fois"},{"enonce":"Quelle solidarité domine à Corbeil ?","aide":"Quand les métiers se multiplient, sur quoi repose l’unité ?","type":"choix","options":[{"id":"a","texte":"Aucune solidarité : la division du travail a détruit tout lien entre les habitants"},{"id":"b","texte":"La solidarité mécanique : les habitants se ressemblent par leur métier et leurs croyances communes"},{"id":"c","texte":"La solidarité organique : les habitants dépendent les uns des autres pour des fonctions complémentaires"},{"id":"d","texte":"La solidarité mécanique, parce que l’agriculture y reste le seul métier indispensable"}],"multiple":false},{"enonce":"Dans quel cas la solidarité organique ne se construit-elle pas ?","aide":"Pense aux règles qui encadrent la division du travail.","type":"choix","options":[{"id":"a","texte":"Quand les habitants exercent des métiers trop différents de ceux de leurs parents"},{"id":"b","texte":"Quand la ville compte moins d’habitants que n’en comptait le village d’origine"},{"id":"c","texte":"Quand la division du travail est anomique, sans règles reconnues qui l’encadrent"},{"id":"d","texte":"Quand les métiers sont trop nombreux pour que les habitants puissent se connaître"}],"multiple":false},{"enonce":"Associe chaque auteur à son apport.","aide":"Trois auteurs, trois notions du chapitre.","type":"association","gauche":[{"id":"g0","texte":"Durkheim"},{"id":"g1","texte":"Castel"},{"id":"g2","texte":"Schnapper"}],"droite":[{"id":"d0","texte":"Le chômage désorganise le temps et l’identité"},{"id":"d1","texte":"Désaffiliation, un continuum"},{"id":"d2","texte":"Solidarité mécanique et organique"}]}]}$ex$::jsonb,
