  ('fe7bacb2-6584-59ec-be90-866c78b5ce8c'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le basculement de Noé","competence":"analyser-document","situation":"Noé a été intégré, puis vulnérable, puis a perdu ses repères. Un tableau imaginaire suit son parcours entre 2016 et 2024 : le travail et les relations.","documents":[{"id":"noe","type":"tableau","titre":"Le parcours de Noé","source":"Parcours imaginé pour l’exercice.","colonnes":["Année","Travail","Relations"],"lignes":[["2016","CDI","Famille, collègues, amis"],["2018","CDD renouvelé","Collègues perdus, amis gardés"],["2020","Intérim, missions de deux semaines","Famille et quelques amis"],["2022","Sans emploi","Famille seulement"],["2024","Sans emploi depuis deux ans","Plus de contacts réguliers"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’année où Noé quitte pour la première fois la zone d’intégration.","aide":"Il est intégré tant qu’il a un emploi stable et des relations solides.","type":"zone","document":"noe","multiple":false},{"enonce":"Combien d’années séparent le CDI de Noé de sa situation de 2024 ?","aide":"Soustrais les années lues dans le tableau.","type":"nombre","unite":"ans"},{"enonce":"Range chaque personne selon sa position dans le continuum de Castel.","aide":"Regarde à la fois le travail et les relations.","type":"categories","categories":[{"id":"c0","texte":"Intégration"},{"id":"c1","texte":"Vulnérabilité"},{"id":"c2","texte":"Désaffiliation"}],"items":[{"id":"i0","texte":"Paul : sans emploi depuis quatre ans, ne voit plus personne"},{"id":"i1","texte":"Karim : missions d’intérim, famille présente mais collègues perdus"},{"id":"i2","texte":"Hélène : CDI depuis dix ans, famille et amis proches"},{"id":"i3","texte":"Sofia : CDD renouvelé, bon réseau d’amis"}]},{"enonce":"Pourquoi le basculement vers la désaffiliation reste-t-il longtemps invisible ?","aide":"Regarde comment évoluent les lignes du tableau de 2016 à 2024.","type":"choix","options":[{"id":"a","texte":"Il est progressif : chaque étape ressemble à la précédente et rien ne le signale nettement"},{"id":"b","texte":"Il concerne uniquement des personnes qui refusent volontairement tout contact avec autrui"},{"id":"c","texte":"Il est brutal et intervient du jour au lendemain, sans que personne ne puisse l’anticiper"},{"id":"d","texte":"Il est masqué par l’administration, qui cache volontairement les statistiques des situations concernées"}],"multiple":false}]}$ex$::jsonb,
