e":false},{"enonce":"Quelle formule résume le mieux le processus décrit par le premier tableau ?","aide":"Schumpeter insiste sur les deux faces à la fois.","type":"choix","options":[{"id":"a","texte":"Une destruction créatrice : douloureuse à court terme, créatrice de croissance à long terme"},{"id":"b","texte":"Une décroissance choisie : moins de production pour préserver le capital naturel"},{"id":"c","texte":"Une croissance extensive : plus de travail et plus de capital, sans changement technique"},{"id":"d","texte":"Une stagnation séculaire : aucune activité nouvelle ne remplace les activités détruites"}],"multiple":false}]}$ex$::jsonb,
