  ('d5838efd-0ecb-5c9e-94c6-c3a260895987'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux pays, deux règles du jeu","competence":"analyser-document","situation":"Noria et Sudland, deux pays imaginaires, ont le même capital et la même main-d’œuvre. Ils n’innovent pourtant pas au même rythme. Les institutions y sont très différentes.","documents":[{"id":"pays","type":"tableau","titre":"Noria et Sudland","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Noria","Sudland"],"lignes":[["Délai pour créer une entreprise (jours)",5,150],["Brevets déposés par million d’habitants",250,10],["Durée d’un procès pour faire respecter un contrat (jours)",400,1200]],"enteteLignes":true}],"questions":[{"enonce":"Touche le délai de création d’une entreprise à Sudland.","aide":"Première ligne, colonne du pays qui innove peu.","type":"zone","document":"pays","multiple":false},{"enonce":"Combien de fois le délai de création d’une entreprise est-il plus long à Sudland qu’à Noria ?","aide":"Divise 150 par 5.","type":"nombre","unite":"fois"},{"enonce":"Range chaque règle selon la famille d’institutions à laquelle elle appartient.","aide":"Pense à qui détient le pouvoir et à qui profite la règle.","type":"categories","categories":[{"id":"c0","texte":"Institutions inclusives"},{"id":"c1","texte":"Institutions extractives"}],"items":[{"id":"i0","texte":"Le pouvoir politique est largement réparti entre plusieurs contre-pouvoirs"},{"id":"i1","texte":"Les droits de propriété sont garantis à tous par une justice indépendante"},{"id":"i2","texte":"Les licences d’activité sont réservées à des proches du pouvoir"},{"id":"i3","texte":"Les nouveaux concurrents sont écartés pour protéger des rentes"}]},{"enonce":"Pourquoi des institutions extractives freinent-elles l’innovation ?","aide":"Qui perd quand une activité nouvelle remplace une activité ancienne ?","type":"choix","options":[{"id":"a","texte":"Les brevets sont toujours interdits dans les pays de ce type d’institutions"},{"id":"b","texte":"La destruction créatrice menace les rentes de ceux qui détiennent le pouvoir"},{"id":"c","texte":"La population active de ces pays est trop peu formée pour pouvoir innover"},{"id":"d","texte":"Les élites n’ont aucun intérêt à faire respecter les contrats des entreprises"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"À Sudland, il faut **150 jours** pour créer une entreprise : un signe d’institutions qui protègent les positions en place."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 fois","explication":"150 ÷ 5 = **30 fois** plus long."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Selon Acemoglu et Robinson, les institutions **inclusives** répartissent le pouvoir et les droits ; les **extractives** les concentrent sur une élite."},{"cle":{"type":"choix","ids":["b"]},"explication":"Une innovation peut ruiner des positions acquises : les élites en place bloquent donc la **destruction créatrice**."}]$ex$::jsonb),
  ('d5838efd-0ecb-5c9e-94c6-c3a260895987'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le vélo pliant des Ateliers Morel","competence":"analyser-document","situation":"Les Ateliers Morel, entreprise imaginaire, ont multiplié les innovations. Mais qui est vraiment l’entrepreneur innovant quand l’invention vient d’ailleurs ?","documents":[{"id":"morel","type":"texte","genre":"article","titre":"Les Ateliers Morel","source":"Texte écrit pour l’exercice.","blocs":["Les Ateliers Morel lancent un vélo électrique pliant, qui n’existait pas dans leur catalogue.","Ils installent des robots de soudure : le coût de revient d’un vélo passe de 400 € à 340 €.","Ils remplacent la chaîne de montage par des équipes qui gèrent elles-mêmes leurs tâches.","Ils ouvrent un marché en Norvège, où ils n’avaient jamais vendu."]},{"id":"qui","type":"tableau","titre":"Qui a fait quoi ?","source":"Situation imaginée pour l’exercice.","colonnes":["Acteur","Rôle"],"lignes":[["Laboratoire public","A mis au point, en 2012, un moteur compact et déposé le brevet"],["Léa Durand","A fondé la société qui a intégré ce moteur dans un vélo et l’a mis sur le marché"]],"enteteLignes":true}],"questions":[{"enonce":"Relie chaque paragraphe du texte au type d’innovation qu’il décrit.","aide":"Produit : un bien nouveau. Procédé : une façon de produire. Organisation : le travail. Débouché : un marché.","type":"association","gauche":[{"id":"g0","texte":"Le vélo électrique pliant"},{"id":"g1","texte":"Les robots de soudure"},{"id":"g2","texte":"Les équipes autonomes"},{"id":"g3","texte":"Le marché norvégien"}],"droite":[{"id":"d0","texte":"Innovation de produit"},{"id":"d1","texte":"Innovation d’organisation"},{"id":"d2","texte":"Innovation de débouché"},{"id":"d3","texte":"Innovation de procédé"}]},{"enonce":"De combien, en %, le coût de revient d’un vélo a-t-il baissé grâce aux robots ?","aide":"Calcule (400 − 340) ÷ 400 × 100.","type":"nombre","unite":"%"},{"enonce":"Touche l’acteur qui est l’entrepreneur innovant au sens de Schumpeter.","aide":"L’entrepreneur n’est pas nécessairement l’inventeur.","type":"zone","document":"qui","multiple":false},{"enonce":"Le laboratoire a déposé un brevet très large couvrant tout moteur de ce type. Quel risque cela fait-il courir à l’innovation ?","aide":"Un brevet protège l’invention, mais aussi ce qu’elle empêche.","type":"choix","options":[{"id":"a","texte":"Obliger les entreprises à publier leurs propres procédés de fabrication"},{"id":"b","texte":"Bloquer les innovations suivantes, qui s’appuient toujours sur les précédentes"},{"id":"c","texte":"Empêcher le laboratoire de recevoir le moindre financement public futur"},{"id":"d","texte":"Supprimer toute incitation à inventer, puisque personne ne protège l’idée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Quatre types d’innovation : **produit**, **procédé**, **organisation**, **débouché**."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 %","explication":"60 ÷ 400 = 0,15, soit **− 15 %**."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"**Léa Durand** : l’entrepreneur est celui qui introduit l’invention sur le marché, pas forcément celui qui l’a imaginée."},{"cle":{"type":"choix","ids":["b"]},"explication":"Un brevet **trop large** ferme la voie aux innovations qui en dépendent : le compromis entre inciter et diffuser est rompu."}]$ex$::jsonb),
  ('effb87c0-4aa5-54e6-8d2b-cfa738b06b3c'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le PIB monte, les émissions aussi ?","competence":"lire-tableau","situation":"Un pays imaginaire suit son PIB et ses émissions de gaz à effet de serre en indice base 100 en 2000.","documents":[{"id":"indices","type":"tableau","titre":"PIB et émissions (base 100 en 2000)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Année","PIB en volume","Émissions"],"lignes":[[2000,100,100],[2010,120,115],[2020,140,95]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’année où les émissions sont repassées sous leur niveau de 2000.","aide":"Cherche un indice inférieur à 100.","type":"zone","document":"indices","multiple":false},{"enonce":"De combien, en %, le PIB a-t-il augmenté entre 2000 et 2020 ?","aide":"L’indice de 2000 vaut 100.","type":"nombre","unite":"%"},{"enonce":"Entre 2000 et 2010, que dit-on de la relation entre PIB et émissions ?","aide":"Compare + 20 % et + 15 %.","type":"choix","options":[{"id":"a","texte":"Une décroissance : le PIB et les émissions baissent en même temps"},{"id":"b","texte":"Un couplage parfait : les émissions croissent exactement comme le PIB"},{"id":"c","texte":"Un découplage absolu : les émissions baissent alors que le PIB augmente"},{"id":"d","texte":"Un découplage relatif : les émissions croissent moins vite que le PIB"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Compare 120 → 140 pour le PIB et 115 → 95 pour les émissions.","type":"trous","segments":["Entre 2010 et 2020, le PIB ",0," et les émissions ",1," : c’est un découplage ",2,"."],"banque":["relatif","augmente","baisse","absolu"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"En **2020**, l’indice des émissions est à 95 : il est repassé sous 100."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 %","explication":"De 100 à 140 : **+ 40 %**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les émissions augmentent (+ 15 %) mais moins que le PIB (+ 20 %) : **découplage relatif**."},{"cle":{"type":"trous","trous":[["augmente"],["baisse"],["absolu"]]},"affichage":"augmente · baisse · absolu","explication":"Le PIB passe de 120 à 140 pendant que les émissions passent de 115 à 95 : **découplage absolu**."}]$ex$::jsonb),
  ('effb87c0-4aa5-54e6-8d2b-cfa738b06b3c'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les émissions qu’on a déplacées","competence":"calculer","situation":"Un pays développé imaginaire se félicite de la baisse de ses émissions. Mais l’empreinte carbone compte aussi les émissions liées à ce qu’il importe. Empreinte = émissions sur le territoire + émissions importées − émissions exportées.","documents":[{"id":"emis","type":"tableau","titre":"Les émissions du pays (millions de tonnes de CO₂)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Année","Sur le territoire","Importées","Exportées"],"lignes":[[2000,500,150,50],[2020,400,230,90]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est l’empreinte carbone du pays en 2000, en millions de tonnes ?","aide":"Applique la formule : 500 + 150 − 50.","type":"nombre","unite":"Mt"},{"enonce":"Quelle est son empreinte carbone en 2020, en millions de tonnes ?","aide":"Même formule avec les chiffres de 2020.","type":"nombre","unite":"Mt"},{"enonce":"De combien, en %, les émissions sur le territoire ont-elles varié entre 2000 et 2020 ? (réponds avec un signe)","aide":"(400 − 500) ÷ 500 × 100.","type":"nombre","unite":"%"},{"enonce":"Pourquoi l’empreinte recule-t-elle bien plus lentement que les émissions du territoire ?","aide":"Regarde l’évolution de la colonne « Importées ».","type":"choix","options":[{"id":"a","texte":"Les émissions importées ont augmenté : des productions polluantes ont été déplacées"},{"id":"b","texte":"Les émissions exportées ont disparu : les usines du pays ont toutes fermé"},{"id":"c","texte":"Les émissions importées ne sont jamais prises en compte dans l’empreinte"},{"id":"d","texte":"Les émissions du territoire ont été comptées deux fois dans les statistiques"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":600,"tolerance":0},"affichage":"600 Mt","explication":"500 + 150 − 50 = **600 Mt**."},{"cle":{"type":"nombre","valeur":540,"tolerance":0},"affichage":"540 Mt","explication":"400 + 230 − 90 = **540 Mt**."},{"cle":{"type":"nombre","valeur":-20,"tolerance":0},"affichage":"−20 %","explication":"(400 − 500) ÷ 500 = **− 20 %** sur le territoire, contre − 10 % pour l’empreinte."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les émissions importées passent de 150 à 230 Mt : une part de la baisse tient à la **délocalisation** des industries polluantes."}]$ex$::jsonb),
  ('effb87c0-4aa5-54e6-8d2b-cfa738b06b3c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La marée noire qui fait monter le PIB","competence":"analyser-document","situation":"Après une marée noire au large d’une région imaginaire, trois personnes donnent leur avis sur l’avenir. Un tableau montre aussi ce que le PIB enregistre.","documents":[{"id":"avis","type":"texte","genre":"source","titre":"Trois avis","source":"Textes écrits pour l’exercice.","blocs":["Inès, ingénieure : « Avec de meilleures machines, nous remplacerons ce que la nature ne fournira plus. »","Malo, écologue : « Une espèce disparue ne se remplace pas : certains éléments sont irremplaçables. »","Zoé, économiste : « Il faut préserver un stock minimal de ressources, quoi qu’il arrive. »"]},{"id":"pib","type":"tableau","titre":"Ce que le PIB enregistre après la marée noire","source":"Chiffres imaginés pour l’exercice, en milliards d’euros.","colonnes":["Élément","Effet sur le PIB"],"lignes":[["PIB avant la marée noire",1000],["Activité de nettoyage","+ 6"],["Pêche et tourisme perdus","− 4"],["Valeur de la zone naturelle détruite","Non comptée"]],"enteteLignes":true}],"questions":[{"enonce":"Range chaque avis selon la conception de la soutenabilité qu’il illustre.","aide":"La soutenabilité faible croit à la substitution des capitaux, la forte la refuse.","type":"categories","categories":[{"id":"c0","texte":"Soutenabilité faible"},{"id":"c1","texte":"Soutenabilité forte"}],"items":[{"id":"i0","texte":"Avis de Zoé : il faut maintenir un stock minimal de capital naturel"},{"id":"i1","texte":"Avis de Malo : certains capitaux sont irremplaçables"},{"id":"i2","texte":"Avis d’Inès : le capital technologique compense la perte de nature"}]},{"enonce":"Quel est le PIB après la marée noire, en milliards d’euros ?","aide":"Ajoute les effets comptés : 1 000 + 6 − 4.","type":"nombre","unite":"milliards"},{"enonce":"Touche la ligne que le PIB ne compte pas du tout.","aide":"Cherche la mention « Non comptée ».","type":"zone","document":"pib","multiple":false},{"enonce":"Que montre ce cas sur l’usage du PIB comme boussole ?","aide":"Le nettoyage est une production, la nature perdue n’est pas comptée.","type":"choix","options":[{"id":"a","texte":"Le PIB baisse toujours quand une catastrophe écologique frappe une région"},{"id":"b","texte":"Le PIB peut monter alors que le capital naturel, et donc le bien-être, se dégrade"},{"id":"c","texte":"Le PIB est inutile, car il ne peut jamais mesurer une production de services"},{"id":"d","texte":"Le PIB mesure le bien-être, puisqu’il inclut le nettoyage d’une pollution"}],"multiple":false},{"enonce":"Quel argument les partisans de la décroissance opposent-ils à la croissance verte ?","aide":"Pense aux données sur le découplage.","type":"choix","options":[{"id":"a","texte":"Le découplage absolu est trop lent et trop partiel pour suffire"},{"id":"b","texte":"Le PIB est la meilleure mesure du bien-être de la population"},{"id":"c","texte":"Les capitaux sont parfaitement substituables entre eux à long terme"},{"id":"d","texte":"Le signal-prix suffira à orienter la production vers des biens propres"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0"}},"explication":"**Faible** : les capitaux sont substituables. **Forte** : certains sont irremplaçables, on doit préserver un stock minimal."},{"cle":{"type":"nombre","valeur":1002,"tolerance":0},"affichage":"1002 milliards","explication":"1 000 + 6 − 4 = **1 002 milliards** : le PIB a légèrement augmenté."},{"cle":{"type":"zone","ids":["r3c0"]},"explication":"La **zone naturelle détruite** n’entre pas dans le PIB : il ignore la destruction du capital naturel."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est la critique la plus solide du PIB : une marée noire le **fait monter**, puisque le nettoyage est une production."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les partisans de la **décroissance** jugent que le découplage absolu ne vient pas assez vite : il faut réduire la production elle-même."}]$ex$::jsonb),
  ('72a6b2dd-22b6-5f01-87b5-dbeba4d0c38d'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Que deviennent les fils d’ouvriers ?","competence":"lire-tableau","situation":"Une table de mobilité imaginaire indique, pour 100 fils de chaque origine, la position qu’ils occupent à l’âge adulte.","documents":[{"id":"dest","type":"tableau","titre":"Position du fils selon le métier du père (en %)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Père","Fils cadre","Fils profession intermédiaire","Fils ouvrier"],"lignes":[["Cadre",55,30,15],["Profession intermédiaire",25,45,30],["Ouvrier",10,30,60]],"enteteLignes":true}],"questions":[{"enonce":"Touche la part de fils d’ouvriers devenus cadres.","aide":"Ligne « Ouvrier », colonne « Fils cadre ».","type":"zone","document":"dest","multiple":false},{"enonce":"Quelle part des fils de cadres est elle-même cadre, en % ?","aide":"Lis la première ligne, première colonne de chiffres.","type":"nombre","unite":"%"},{"enonce":"Quelle part des fils d’ouvriers n’est pas ouvrière, en % ?","aide":"Retranche 60 à 100.","type":"nombre","unite":"%"},{"enonce":"Complète la phrase.","aide":"Additionne les trois cases d’une ligne.","type":"trous","segments":["Ce tableau est une table de ",0," : chaque ligne totalise ",1," %."],"banque":["50","100","recrutement","destinée"]}]}$ex$::jsonb,
