  ('72a6b2dd-22b6-5f01-87b5-dbeba4d0c38d'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Destinée ou recrutement ?","competence":"lire-tableau","situation":"Les mêmes données peuvent se lire de deux façons. Ce tableau d’effectifs imaginaires simplifie la société en deux groupes seulement, cadres et ouvriers.","documents":[{"id":"eff","type":"tableau","titre":"Père et fils (en milliers d’hommes)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Père \\ Fils","Fils cadre","Fils ouvrier","Total"],"lignes":[["Père cadre",100,100,200],["Père ouvrier",80,720,800]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’effectif des fils d’ouvriers devenus cadres.","aide":"Ligne du père ouvrier, colonne du fils cadre.","type":"zone","document":"eff","multiple":false},{"enonce":"Table de destinée : quelle part des fils d’ouvriers devient cadre, en % ?","aide":"Divise 80 par le total de la ligne « Père ouvrier ».","type":"nombre","unite":"%"},{"enonce":"Table de recrutement : quelle part des fils cadres a un père ouvrier, en % ? (arrondi au dixième)","aide":"Le total des fils cadres est la somme de la colonne « Fils cadre ».","type":"nombre","unite":"%"},{"enonce":"Range chaque phrase selon la table qui permet de la justifier.","aide":"Destinée : on part de l’origine. Recrutement : on part de la position d’arrivée.","type":"categories","categories":[{"id":"c0","texte":"Table de destinée"},{"id":"c1","texte":"Table de recrutement"}],"items":[{"id":"i0","texte":"Les cadres viennent majoritairement d’un père cadre"},{"id":"i1","texte":"Parmi les cadres, 44 % ont un père ouvrier"},{"id":"i2","texte":"La moitié des fils de cadres deviennent cadres"},{"id":"i3","texte":"Un fils d’ouvrier sur dix devient cadre"}]},{"enonce":"Pourquoi 44 % des cadres sont-ils fils d’ouvriers alors que 10 % seulement des fils d’ouvriers deviennent cadres ?","aide":"Compare les totaux de départ : 200 contre 800.","type":"choix","options":[{"id":"a","texte":"Les fils de cadres deviennent très rarement cadres dans ce tableau"},{"id":"b","texte":"Les groupes n’ont pas la même taille : il y a beaucoup plus de fils d’ouvriers"},{"id":"c","texte":"Les cadres recrutent de préférence parmi les enfants de familles ouvrières"},{"id":"d","texte":"Les tables de destinée sont fausses, celles de recrutement sont exactes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"Ils sont **80 000** fils d’ouvriers devenus cadres."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 %","explication":"80 ÷ 800 = **10 %**."},{"cle":{"type":"nombre","valeur":44.4,"tolerance":0.1},"affichage":"44,4 %","explication":"Il y a 180 000 fils cadres, dont 80 000 de père ouvrier : 80 ÷ 180 ≈ **44,4 %**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"La **destinée** se lit en ligne (« que deviennent-ils ? »), le **recrutement** en colonne (« d’où viennent-ils ? »)."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les deux lectures donnent des chiffres différents parce que les **groupes sont de tailles différentes** : 800 000 fils d’ouvriers contre 200 000 fils de cadres."}]$ex$::jsonb),
  ('72a6b2dd-22b6-5f01-87b5-dbeba4d0c38d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Beaucoup de mobilité, peu de fluidité","competence":"analyser-document","situation":"La structure des emplois se transforme : il y a de plus en plus de postes de cadres. Une partie de la mobilité est donc imposée. Deux pays imaginaires sont comparés.","documents":[{"id":"struct","type":"tableau","titre":"La place des cadres dans la population active","source":"Chiffres imaginés pour l’exercice.","colonnes":["Génération","Part de cadres"],"lignes":[["Pères","10 %"],["Fils","25 %"]],"enteteLignes":true},{"id":"mobi","type":"tableau","titre":"Mobilité observée et mobilité imposée (en % des fils)","source":"Chiffres imaginés pour l’exercice.","colonnes":["Pays","Mobilité observée","Mobilité imposée par la structure des emplois"],"lignes":[["Pays P",64,42],["Pays Q",50,20]],"enteteLignes":true}],"questions":[{"enonce":"De combien de points la part des cadres augmente-t-elle entre les pères et les fils ?","aide":"Soustrais 10 à 25.","type":"nombre","unite":"points"},{"enonce":"Quelle est la mobilité nette (hors effet de structure) du pays P, en points ?","aide":"Retranche la mobilité imposée à la mobilité observée.","type":"nombre","unite":"points"},{"enonce":"Quelle est la mobilité nette du pays Q, en points ?","aide":"Même calcul pour le pays Q.","type":"nombre","unite":"points"},{"enonce":"Quel pays a la fluidité sociale la plus forte ?","aide":"La fluidité est la mobilité qui reste une fois l’effet de structure retiré.","type":"choix","options":[{"id":"a","texte":"Les deux pays sont à égalité, car la structure des emplois change"},{"id":"b","texte":"Le pays Q, malgré une mobilité observée plus faible"},{"id":"c","texte":"Le pays P, parce que sa mobilité observée est la plus forte"},{"id":"d","texte":"Aucun des deux : la fluidité ne peut pas se calculer avec ces données"}],"multiple":false},{"enonce":"Que montre cette comparaison ?","aide":"Compare le classement des pays selon les deux mesures.","type":"choix","options":[{"id":"a","texte":"Une mobilité observée élevée garantit toujours une société très ouverte"},{"id":"b","texte":"La structure des emplois n’a aucun effet sur la mobilité des individus"},{"id":"c","texte":"Beaucoup de mobilité observée peut coexister avec peu de fluidité sociale"},{"id":"d","texte":"La fluidité sociale s’obtient en additionnant mobilité observée et imposée"}],"multiple":false}]}$ex$::jsonb,
