   $ex${"titre":"Ce qui joue sur la trajectoire","competence":"analyser-document","situation":"Quatre personnes imaginaires racontent leur parcours. Chacune illustre un facteur de la mobilité sociale. Un tableau montre aussi ce que devient le diplôme.","documents":[{"id":"parcours","type":"texte","genre":"source","titre":"Quatre parcours","source":"Textes écrits pour l’exercice.","blocs":["Sarah entre sur le marché du travail en pleine récession et enchaîne des contrats courts pendant des années.","Hugo a grandi dans une maison pleine de livres, et ses parents l’ont toujours soutenu financièrement dans ses études.","Camille et Yanis, tous deux enfants de cadres, se rencontrent en classe préparatoire et forment un couple.","Samir devient cadre alors que son père était agriculteur : il y avait beaucoup plus de postes de cadres que de son temps."]},{"id":"diplome","type":"tableau","titre":"Le rendement du diplôme","source":"Chiffres imaginés pour l’exercice.","colonnes":["Génération","Part de diplômés du supérieur (%)","Part d’entre eux cadres à 35 ans (%)"],"lignes":[["Entrée sur le marché en 1990",15,80],["Entrée sur le marché en 2020",45,55]],"enteteLignes":true}],"questions":[{"enonce":"Relie chaque parcours au facteur de mobilité sociale qu’il illustre.","aide":"Chaque histoire met en avant un seul facteur.","type":"association","gauche":[{"id":"g0","texte":"Sarah"},{"id":"g1","texte":"Hugo"},{"id":"g2","texte":"Camille et Yanis"},{"id":"g3","texte":"Samir"}],"droite":[{"id":"d0","texte":"L’homogamie"},{"id":"d1","texte":"La famille et son capital culturel"},{"id":"d2","texte":"La conjoncture"},{"id":"d3","texte":"La structure des emplois"}]},{"enonce":"Combien de fois la part de diplômés du supérieur est-elle plus grande pour l’entrée en 2020 que pour l’entrée en 1990 ?","aide":"Divise 45 par 15.","type":"nombre","unite":"fois"},{"enonce":"Touche la part de diplômés devenus cadres à 35 ans pour l’entrée sur le marché en 2020.","aide":"Deuxième ligne, dernière colonne.","type":"zone","document":"diplome","multiple":false},{"enonce":"De combien de points la part des diplômés cadres à 35 ans a-t-elle varié ? (réponds avec un signe)","aide":"Soustrais 80 à 55.","type":"nombre","unite":"points"},{"enonce":"Que montre ce tableau sur le rôle de l’École ?","aide":"Plus de diplômés, mais moins d’entre eux deviennent cadres.","type":"choix","options":[{"id":"a","texte":"Elle ne joue plus aucun rôle, puisque la part de cadres chez les diplômés baisse"},{"id":"b","texte":"Elle ne joue aucun rôle, puisque la famille détermine seule la trajectoire"},{"id":"c","texte":"Elle garantit un poste de cadre, puisque la part de diplômés triple en trente ans"},{"id":"d","texte":"Elle reste un vecteur de mobilité, mais son rendement se dégrade avec l’inflation scolaire"}],"multiple":false}]}$ex$::jsonb,
