   $ex${"titre":"Construire un avantage","competence":"analyser-document","situation":"Le pays imaginaire de Zélandia vendait surtout des produits agricoles en 1960. Quarante ans plus tard, il est l’un des premiers exportateurs d’électronique.","documents":[{"id":"frise","type":"frise","titre":"La trajectoire de Zélandia","source":"Dates imaginées pour l’exercice.","debut":1960,"fin":2010,"pas":10,"evenements":[{"id":"z1","date":1965,"nom":"Protection"},{"id":"z2","date":1975,"nom":"Écoles ingénieurs"},{"id":"z3","date":1985,"nom":"Protection levée"},{"id":"z4","date":2005,"nom":"Leader mondial"}]},{"id":"part","type":"tableau","titre":"Zélandia en chiffres","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","1965","1995"],"lignes":[["Ingénieurs diplômés pour 10 000 habitants",2,12],["Électronique dans les exportations (%)",1,30]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’événement qui marque la fin du protectionnisme éducateur.","aide":"La protection est levée quand l’industrie a mûri.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années a duré la protection ?","aide":"Soustrais la date de début à celle de fin.","type":"nombre","unite":"ans"},{"enonce":"Par combien le nombre d’ingénieurs diplômés a-t-il été multiplié entre 1965 et 1995 ?","aide":"Divise 12 par 2.","type":"nombre","unite":"fois"},{"enonce":"Que montre ce cas sur les avantages comparatifs ?","aide":"Zélandia n’avait aucun avantage dans l’électronique en 1960.","type":"choix","options":[{"id":"a","texte":"Ils se construisent par la formation, la recherche et parfois une protection temporaire"},{"id":"b","texte":"Ils ne dépendent que du niveau des salaires par rapport aux autres pays"},{"id":"c","texte":"Ils sont donnés une fois pour toutes par les ressources naturelles du pays"},{"id":"d","texte":"Ils disparaissent dès qu’un pays cesse de protéger toutes ses industries"}],"multiple":false},{"enonce":"Pourquoi le modèle HOS, pris seul, explique-t-il mal cette trajectoire ?","aide":"HOS part des dotations en facteurs du pays.","type":"choix","options":[{"id":"a","texte":"Il suppose que les consommateurs exigent des produits tous différents"},{"id":"b","texte":"Il part de dotations données et ne dit pas comment elles évoluent"},{"id":"c","texte":"Il affirme que tous les pays doivent produire tous les biens à la fois"},{"id":"d","texte":"Il ignore totalement le rôle des facteurs de production dans l’échange"}],"multiple":false}]}$ex$::jsonb,
